fn install_method(
    vm: &mut Vm,
    table: TableId,
    name: &str,
    op: Op,
    store: &Shared,
    captures: &[Value],
) -> Result<(), Error> {
    let function = vm.new_host_function_with_data(
        callback,
        captures,
        Binding {
            store: store.clone(),
            op,
        },
    )?;
    super::put(vm, table, name, function)
}
fn table(call: &HostCall<'_>, value: Value) -> Result<TableId, Error> {
    if let Value::Table(id) = value {
        Ok(id)
    } else {
        Err(call.error(b"actor table expected"))
    }
}
fn get(call: &mut HostCall<'_>, t: TableId, key: &[u8]) -> Result<Value, Error> {
    let key = call.try_intern(key)?;
    call.raw_table_get(t, key)
}
fn bytes(call: &mut HostCall<'_>, value: Value) -> Result<Vec<u8>, Error> {
    let id = call
        .coerce_string(value)?
        .ok_or_else(|| call.error(b"string expected"))?;
    Ok(call.string_bytes(id).unwrap().to_vec())
}
fn arg(call: &HostCall<'_>, i: usize) -> Value {
    call.arguments().get(i).copied().unwrap_or(Value::Nil)
}
fn helper(call: &HostCall<'_>, index: usize) -> Result<Value, Error> {
    let Value::Table(helpers) = call.captures()[1] else {
        unreachable!()
    };
    call.raw_table_get(helpers, Value::Number(index as f64))
}
fn declared_children(store: &Shared, actor: TableId) -> Vec<TableId> {
    store.lock().unwrap().actors[&actor].children.clone()
}
fn children(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<Vec<TableId>, Error> {
    if has_native_children(store, actor) {
        native_children::children(call, store, actor)
    } else {
        Ok(declared_children(store, actor))
    }
}
fn has_native_children(store: &Shared, actor: TableId) -> bool {
    let store = store.lock().unwrap();
    let actor = &store.actors[&actor];
    actor.native_children
        || matches!(
            actor.state.class,
            "GraphDisplay"
                | "SongMeterDisplay"
                | "CourseContentsList"
                | "Model"
                | "PlayerActor"
                | "HoldJudgment"
                | "NoteField"
        )
}
fn is_frame(store: &Shared, actor: TableId) -> bool {
    matches!(
        store.lock().unwrap().actors[&actor].state.class,
        "ActorFrame"
            | "PlayerActor"
            | "HoldJudgment"
            | "PercentageDisplay"
            | "StepsDisplay"
            | "TopScreen"
            | "NoteField"
            | "ActorFrameTexture"
            | "WrapperState"
            | "GraphDisplay"
            | "SongMeterDisplay"
            | "CourseContentsList"
    )
}
fn sort(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    for child in declared_children(store, actor) {
        if store.lock().unwrap().actors[&child].raw_instance {
            let value = get(call, child, b"__songlua_state_draw_order")?;
            let n = sprites::number(call, value).unwrap_or(0.);
            let order = if n > -2147483649. && n < 2147483648. {
                n as i32
            } else {
                0
            };
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&child)
                .unwrap()
                .state
                .draw_order = order;
        }
    }
    let list = {
        let mut store = store.lock().unwrap();
        let mut list = store.actors[&actor].children.clone();
        list.sort_by_key(|id| store.actors[id].state.draw_order);
        store.actors.get_mut(&actor).unwrap().children = list.clone();
        list
    };
    for (index, child) in list.into_iter().enumerate() {
        call.raw_table_set(
            actor,
            Value::Number((index + 1) as f64),
            Value::Table(child),
        )?;
    }
    Ok(())
}
fn command(
    call: &mut HostCall<'_>,
    actor: TableId,
    name: &[u8],
) -> Result<Option<(Value, Vec<u8>)>, Error> {
    let mut field = [name, b"Command"].concat();
    for fallback in [false, true] {
        if fallback {
            if name.ends_with(b"Message") {
                break;
            }
            field = [name, b"MessageCommand"].concat();
        }
        let key = call.try_intern(&field)?;
        let value = call.table_get(Value::Table(actor), key)?;
        match value {
            Value::Function(_) | Value::Native(_) => return Ok(Some((value, field))),
            Value::Nil => {}
            _ => return Err(call.error(b"actor command must be a function")),
        }
    }
    Ok(None)
}
fn run(
    call: &mut HostCall<'_>,
    actor: TableId,
    function: Value,
    params: Option<Value>,
) -> Result<(), Error> {
    match params {
        Some(params) => call.call(function, &[Value::Table(actor), params])?,
        None => call.call(function, &[Value::Table(actor)])?,
    };
    Ok(())
}
fn run_scoped(
    call: &mut HostCall<'_>,
    actor: TableId,
    function: Value,
    params: Option<Value>,
) -> Result<(), Error> {
    let key = call.try_intern(b"__songlua_script_dir")?;
    let directory = call.table_get(Value::Table(actor), key)?;
    if directory == Value::Nil {
        return run(call, actor, function, params);
    }
    let directory = bytes(call, directory)?;
    let text = std::str::from_utf8(&directory)
        .map_err(|_| call.error(b"actor script directory must be UTF-8"))?;
    if text.trim().is_empty() {
        return run(call, actor, function, params);
    }
    let directory = call.try_intern(&directory)?;
    call.with_roots(&[directory, key], |call| {
        let globals = helper(call, 5)?;
        let previous = call.table_get(globals, key)?;
        call.with_roots(&[previous], |call| {
            call.table_set(globals, key, directory)?;
            let result = run(call, actor, function, params);
            // Restore the caller's directory even when a callback errors or
            // exhausts its instruction budget. This runs outside authored Lua.
            let globals_table = table(call, globals)?;
            if call.raw_table_get(globals_table, key)? != Value::Nil {
                // An existing field bypasses __newindex. Restore it without
                // entering the VM again after an exhausted instruction budget.
                call.raw_table_set(globals_table, key, previous)?;
            } else {
                call.table_set(globals, key, previous)?;
            }
            result
        })
    })
}
fn run_named(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &[u8],
    params: Option<Value>,
) -> Result<(), Error> {
    run_named_with_drain(call, store, actor, name, params, true)
}
fn run_named_with_drain(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &[u8],
    params: Option<Value>,
    drain: bool,
) -> Result<(), Error> {
    let Some((function, field)) = command(call, actor, name)? else {
        return Ok(());
    };
    let inserted = store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .active_commands
        .insert(field.clone());
    if !inserted {
        return Ok(());
    }
    let previous_capture_start = capture::command_start(store, actor);
    // Keep the selected function alive if a callback replaces its own field or
    // forces GC. Never retain the store lock while entering authored Lua.
    let result = call.with_roots(&[function, params.unwrap_or(Value::Nil)], |call| {
        let theme = call.call(helper(call, 4)?, &[function])?[0] == Value::Boolean(true);
        match run_scoped(call, actor, function, params) {
            Err(error) if theme && error.kind() == ErrorKind::Runtime => {
                store.lock().unwrap().diagnostics.push(error.to_string());
                Ok(())
            }
            result => result,
        }
    });
    let result = result.and_then(|()| {
        if drain && previous_capture_start.is_some() {
            capture::drain_commands(call, store, actor)?;
        }
        Ok(())
    });
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .active_commands
        .remove(&field);
    capture::command_end(store, actor, previous_capture_start);
    result
}
fn play(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &[u8],
    params: Option<Value>,
    recurse: bool,
) -> Result<(), Error> {
    run_named(call, store, actor, name, params)?;
    if recurse {
        for child in children(call, store, actor)? {
            play(call, store, child, name, params, true)?;
        }
    }
    Ok(())
}
fn leaves(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    action: &mut impl FnMut(&mut HostCall<'_>, TableId) -> Result<(), Error>,
) -> Result<(), Error> {
    let children = children(call, store, actor)?;
    if children.is_empty() {
        action(call, actor)?;
    } else {
        for child in children {
            leaves(call, store, child, action)?;
        }
    }
    Ok(())
}
fn release(call: &mut HostCall<'_>, store: &Shared, id: u64) -> Result<bool, Error> {
    if store.lock().unwrap().retired_scenes.contains_key(&id) {
        return Ok(false);
    }
    store.lock().unwrap().constructor_scenes.remove(&id);
    let scene = store.lock().unwrap().scenes.remove(&id);
    let Some(scene) = scene else { return Ok(false) };
    lifecycle::invalidate_plans(call, store)?;
    // Course displays can be shared tables. A scene retires only its last
    // ownership of those actors, including their callbacks and registry roots.
    let mut retired = HashSet::new();
    let mut transferred = Vec::new();
    {
        let mut guard = store.lock().unwrap();
        for &actor in &scene.actors {
            let other = guard
                .scenes
                .iter()
                .filter(|(_, scene)| scene.actors.contains(&actor))
                .min_by_key(|(id, _)| guard.retired_scenes.contains_key(id))
                .map(|(id, _)| *id);
            if let Some(other) = other {
                if guard.retired_scenes.contains_key(&other) {
                    transferred.push((actor, other));
                }
                if let Some(instance) = guard.actors.get_mut(&actor)
                    && instance.scene == id
                {
                    instance.scene = other;
                }
            } else {
                retired.insert(actor);
            }
        }
    }
    store
        .lock()
        .unwrap()
        .actor_order
        .retain(|actor| !retired.contains(actor));
    if let Some(queued) = &mut store.lock().unwrap().startup_queues {
        queued.retain(|actor| !retired.contains(actor));
    }
    let registry = table(call, call.captures()[0])?;
    for (actor, other) in transferred {
        retirement::retain(call, store, other, actor, registry)?;
        call.raw_table_set(registry, Value::Table(actor), Value::Nil)?;
        store.lock().unwrap().retired_subscriptions.remove(&actor);
        store
            .lock()
            .unwrap()
            .actor_order
            .retain(|value| *value != actor);
    }
    for actor in scene.actors {
        if !retired.contains(&actor) {
            continue;
        }
        if !scene.sounds_retired {
            sound::retire(call, store, actor);
        }
        call.raw_table_set(registry, Value::Table(actor), Value::Nil)?;
        let mut store = store.lock().unwrap();
        store.actors.remove(&actor);
        store.retired_subscriptions.remove(&actor);
        #[cfg(feature = "test-support")]
        store.message_ranks.remove(&actor);
    }
    Ok(true)
}
fn build(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    node: TableId,
    parent: Option<TableId>,
    check_condition: bool,
    internal: bool,
) -> Result<Option<TableId>, Error> {
    let attrs = table(call, call.raw_table_get(node, Value::Number(1.0))?)?;
    if check_condition && get(call, attrs, b"Condition")? == Value::Boolean(false) {
        return Ok(None);
    }
    let template = match call.raw_table_get(node, Value::Number(3.0))? {
        Value::Table(source) => store
            .lock()
            .unwrap()
            .actors
            .get(&source)
            .map(TemplateState::from),
        _ => None,
    };
    let class = if let Some(template) = &template {
        template.state.class.as_bytes().to_vec()
    } else {
        let mut kind = get(call, attrs, b"Class")?;
        if kind == Value::Nil {
            kind = get(call, attrs, b"Type")?;
        }
        if kind == Value::Nil {
            Vec::new()
        } else {
            bytes(call, kind)?
        }
    };
    let dummy = class.is_empty();
    let class = match class.as_slice() {
        b"" | b"Actor" => "Actor",
        b"ActorFrame" => "ActorFrame",
        b"ActorFrameTexture" => "ActorFrameTexture",
        b"WrapperState" => "WrapperState",
        b"Quad" => "Quad",
        b"Sprite" => "Sprite",
        b"Banner" => "Banner",
        b"GraphDisplay" => "GraphDisplay",
        b"SongMeterDisplay" => "SongMeterDisplay",
        b"CourseContentsList" => "CourseContentsList",
        b"Model" => "Model",
        b"PlayerActor" if internal => "PlayerActor",
        b"HoldJudgment" if internal => "HoldJudgment",
        b"PercentageDisplay" if internal => "PercentageDisplay",
        b"StepsDisplay" if internal => "StepsDisplay",
        b"TopScreen" if internal => "TopScreen",
        b"OptionRow" if internal => "OptionRow",
        b"OptionRowFrame" if internal => "OptionRowFrame",
        b"Timer" if internal => "Timer",
        b"NoteField" if internal => "NoteField",
        b"NoteColumnRenderer" if internal => "NoteColumnRenderer",
        b"LifeMeter" if internal => "LifeMeter",
        b"GraphDisplayBody" if internal => "GraphDisplayBody",
        b"GraphDisplayLine" if internal => "GraphDisplayLine",
        b"BitmapText" => "BitmapText",
        b"RollingNumbers" => "RollingNumbers",
        b"BPMDisplay" => "BPMDisplay",
        b"DeviceList" => "DeviceList",
        b"InputList" => "InputList",
        b"ActorMultiVertex" => "ActorMultiVertex",
        b"ActorProxy" => "ActorProxy",
        b"Sound" => "Sound",
        _ => {
            return Err(call.error(
                format!(
                    "actor class '{}' has no Rust instance implementation yet",
                    String::from_utf8_lossy(&class)
                )
                .as_bytes(),
            ));
        }
    };
    let create = helper(call, 1)?;
    let kind = call.try_intern(class.as_bytes())?;
    let empty_attrs = if dummy {
        Value::Table(call.try_new_table()?)
    } else {
        Value::Table(attrs)
    };
    let actor = call.call(
        create,
        &[
            kind,
            parent.map_or(Value::Nil, Value::Table),
            empty_attrs,
            Value::Boolean(template.is_some()),
        ],
    )?[0];
    let actor = table(call, actor)?;
    if matches!(class, "Quad" | "ActorMultiVertex") && template.is_none() {
        let key = call.try_intern(b"__songlua_default_texture")?;
        call.raw_table_set(actor, key, Value::Boolean(true))?;
    }
    let mut name = get(call, attrs, b"Name")?;
    // Constructors can name a raw CourseContentsList Display before the same
    // declaration is materialized as an ordinary child.
    if name == Value::Nil
        && let Value::Table(source) = call.raw_table_get(node, Value::Number(3.))?
    {
        name = get(call, source, b"Name")?;
        if name != Value::Nil {
            sprites::set(call, actor, "Name", name)?;
        }
    }
    let load_name = if dummy || name == Value::Nil {
        None
    } else {
        Some(bytes(call, name)?)
    };
    let registry = table(call, call.captures()[0])?;
    retirement::retain(call, store, scene, actor, registry)?;
    {
        let mut store = store.lock().unwrap();
        store.scenes.get_mut(&scene).unwrap().actors.push(actor);
        let deferred = store.defer_registration && !internal && !dummy;
        let mut instance = Actor::new(
            scene,
            class,
            if deferred { None } else { parent },
            load_name,
        );
        instance.pending_init = deferred;
        instance.registered = !deferred;
        if deferred {
            instance.state.name = instance.load_name.clone().unwrap_or_default();
        } else {
            store.actor_order.push(actor);
        }
        if store.constructing_capture {
            instance.capture = Some(capture::Capture::default());
        }
        if let Some(template) = &template {
            // Production clones native fields into a fresh actor at its last
            // destination. Its existing tween queue does not advance or become
            // the clone's queue; independent hibernation and immediate fields
            // are retained. Init still runs normally on the new instance.
            instance.current = template.pose;
            instance.hibernate = template.hibernate;
            instance.update_rate = template.update_rate;
            instance.propagate = template.propagate;
            instance.update_error_reported = template.update_error_reported;
            instance.state.size = template.state.size;
            instance.state.visible = template.state.visible;
            instance.state.draw_order = template.state.draw_order;
            instance.state.render = template.state.render;
            instance.state.rotation = template.state.rotation;
            instance.effects = template.effects;
            if store.preparing {
                instance.capture = template.capture.clone().or(instance.capture);
                instance.preparation_getters = template.preparation_getters;
                instance.offline_instance = true;
            }
        }
        store.actors.insert(actor, instance);
    }
    initialize_resources(
        call,
        store,
        scene,
        actor,
        class,
        if template.is_some() {
            ResourceMode::Template
        } else {
            ResourceMode::Constructor
        },
    )?;
    if dummy {
        return Ok(Some(actor));
    }
    if matches!(
        class,
        "ActorFrame"
            | "PlayerActor"
            | "HoldJudgment"
            | "PercentageDisplay"
            | "StepsDisplay"
            | "TopScreen"
            | "NoteField"
            | "ActorFrameTexture"
            | "GraphDisplay"
            | "SongMeterDisplay"
            | "CourseContentsList"
            | "Model"
    ) {
        let nodes = table(call, call.raw_table_get(node, Value::Number(2.))?)?;
        let mut selected = nodes;
        let mut array_only = true;
        for i in 1..=call.raw_table_len(nodes)? {
            let entry = table(call, call.raw_table_get(nodes, Value::Number(i as f64))?)?;
            let key = call.raw_table_get(entry, Value::Number(1.))?;
            if bytes(call, key)? == b"children" {
                let node = table(call, call.raw_table_get(entry, Value::Number(2.))?)?;
                selected = table(call, call.raw_table_get(node, Value::Number(2.))?)?;
                array_only = false;
                break;
            }
        }
        for i in 1..=call.raw_table_len(selected)? {
            let entry = table(call, call.raw_table_get(selected, Value::Number(i as f64))?)?;
            let name = call.raw_table_get(entry, Value::Number(1.))?;
            let name = bytes(call, name)?;
            if array_only && (name.is_empty() || !name.iter().all(u8::is_ascii_digit)) {
                continue;
            }
            let child = table(call, call.raw_table_get(entry, Value::Number(2.))?)?;
            if let Some(child) = build(call, store, scene, child, Some(actor), true, false)? {
                store
                    .lock()
                    .unwrap()
                    .actors
                    .get_mut(&actor)
                    .unwrap()
                    .children
                    .push(child);
                let index = store.lock().unwrap().actors[&actor].children.len();
                call.raw_table_set(actor, Value::Number(index as f64), Value::Table(child))?;
            }
        }
    }
    Ok(Some(actor))
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum ResourceMode {
    Constructor,
    Template,
    OfflineClone,
    Dummy,
}

fn initialize_resources(
    call: &mut HostCall<'_>,
    store: &Shared,
    scene: u64,
    actor: TableId,
    class: &'static str,
    mode: ResourceMode,
) -> Result<(), Error> {
    let template = mode != ResourceMode::Constructor;
    let bind_only = matches!(mode, ResourceMode::OfflineClone | ResourceMode::Dummy);
    if class == "Sound" {
        sound::install(call, store, actor)?;
    }
    proxies::install(call, actor, class == "ActorProxy")?;
    textures::install_getter(call, store, actor)?;
    if !template {
        render::initialize(call, store, actor)?;
    }
    if class == "Model" {
        models::initialize(call, store, actor, template)?;
    }
    if text_displays::is_display(class) {
        text_displays::install(call, actor)?;
        if !bind_only && let Some(text) = crate::input_status_actor_text(class) {
            let value = call.try_intern(text.as_bytes())?;
            sprites::set(call, actor, "Text", value)?;
        }
    }
    if matches!(
        class,
        "GraphDisplay" | "GraphDisplayBody" | "GraphDisplayLine"
    ) {
        graphs::install(call, actor)?;
    }
    if class == "GraphDisplay" && !bind_only {
        graphs::initialize(call, store, scene, actor)?;
    }
    if class == "CourseContentsList" {
        courses::install(call, actor)?;
        if !bind_only {
            courses::initialize(call, store, scene, actor)?;
        }
    }
    if class == "SongMeterDisplay" {
        song_meters::install(call, actor)?;
        if !bind_only {
            song_meters::initialize(call, store, scene, actor)?;
        }
    }
    if class == "ActorFrameTexture" && !bind_only {
        framebuffers::initialize(call, actor)?;
    }
    if matches!(class, "Sprite" | "Banner") && !bind_only {
        sprites::initialize(call, store, actor, template)?;
    }
    Ok(())
}

fn new_scene(call: &HostCall<'_>, store: &Shared) -> Result<u64, Error> {
    let mut guard = store.lock().unwrap();
    if guard.next >= (1u64 << 53) - 1 {
        return Err(call.error(b"actor scene identity exhausted"));
    }
    guard.next += 1;
    let id = guard.next;
    guard.scenes.insert(
        id,
        Scene {
            actors: Vec::new(),
            root: None,
            ended: false,
            sounds_retired: false,
            initial_states: None,
            song_session: None,
        },
    );
    Ok(id)
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Materialization {
    Template,
    Construct,
    Initialize,
}

// Declaration construction and template cloning share scene ownership. A
// compiler can retain the constructed graph across initial-state capture/Init.
fn materialize(
    call: &mut HostCall<'_>,
    store: &Shared,
    declaration: TableId,
    mode: Materialization,
) -> Result<u64, Error> {
    let offline = {
        let guard = store.lock().unwrap();
        matches!(
            mode,
            Materialization::Construct | Materialization::Initialize
        ) && guard.preparing
            && guard.actors.contains_key(&declaration)
    };
    if offline {
        return offline::own_root(
            call,
            store,
            declaration,
            mode == Materialization::Initialize,
        );
    }
    let node = call.call(helper(call, 2)?, &[Value::Table(declaration)])?[0];
    call.with_roots(&[node], |call| {
        let id = new_scene(call, store)?;
        let previous = {
            let mut guard = store.lock().unwrap();
            std::mem::replace(
                &mut guard.defer_registration,
                mode != Materialization::Template,
            )
        };
        // MakeActor ignores Condition on the root. Only the child loader tests it.
        let result = build(call, store, id, table(call, node)?, None, false, false);
        store.lock().unwrap().defer_registration = previous;
        let result = result.and_then(|root| {
            if mode == Materialization::Initialize
                && let Some(actor) = root
            {
                prepare_init(store);
                initialize(call, store, actor)?;
            }
            Ok(root)
        });
        match result {
            Ok(root) => {
                let mut guard = store.lock().unwrap();
                guard.scenes.get_mut(&id).unwrap().root = root;
                if mode == Materialization::Template
                    && let Some(actor) = root
                {
                    let offline = !guard.clock.live.load(std::sync::atomic::Ordering::Relaxed)
                        && !guard.playback;
                    guard.actors.get_mut(&actor).unwrap().offline_template = offline;
                }
                Ok(id)
            }
            Err(error) => {
                release(call, store, id)?;
                Err(error)
            }
        }
    })
}

fn prepare_init(store: &Shared) {
    let mut guard = store.lock().unwrap();
    if guard.preparing {
        guard.startup_queues.get_or_insert_with(Vec::new);
    }
}

fn initialize(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    if !store.lock().unwrap().actors.contains_key(&actor) {
        return native_children::group_lifecycle(call, store, actor, false);
    }
    if store.lock().unwrap().actors[&actor].offline_instance {
        offline::prepare_init(call, store, actor)?;
    }
    courses::prepare_raw_init(call, store, actor)?;
    if store.lock().unwrap().actors[&actor].initialized {
        return Ok(());
    }
    let original = get(call, actor, b"Name")?;
    call.with_roots(&[original], |call| {
        initialize_body(call, store, actor, original)
    })
}
fn initialize_body(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    original: Value,
) -> Result<(), Error> {
    let raw = {
        let guard = store.lock().unwrap();
        let a = &guard.actors[&actor];
        a.raw_instance || a.offline_instance
    };
    let name = if raw {
        // Raw CourseContentsList displays preserve malformed attributes until
        // a typed getter reads them. prepare_raw_init already applies that rule.
        store.lock().unwrap().actors[&actor].load_name.clone()
    } else if original == Value::Nil {
        None
    } else {
        Some(bytes(call, original)?)
    };
    {
        let mut store = store.lock().unwrap();
        if !store.actor_order.contains(&actor) {
            store.actor_order.push(actor);
        }
        let actor = store.actors.get_mut(&actor).unwrap();
        actor.state.name.clear();
        actor.load_name = name;
        actor.pending_init = false;
        actor.registered = true;
    }
    // The production host materializes the complete tree before Init. Every
    // child is observable while child-first Init applies names and draw order.
    for child in declared_children(store, actor) {
        native_children::adopt_declared(call, store, child, actor)?;
        initialize(call, store, child)?;
    }
    sort(call, store, actor)?;
    {
        let mut store = store.lock().unwrap();
        let actor = store.actors.get_mut(&actor).unwrap();
        if let Some(name) = actor.load_name.take() {
            actor.state.name = name;
        }
    }
    if original != Value::Nil {
        let key = call.try_intern(b"Name")?;
        call.raw_table_set(actor, key, original)?;
    }
    courses::publish_raw_name(call, store, actor, original)?;
    play(call, store, actor, b"Init", None, false)?;
    if let Some(stream) = song_meters::stream(call, store, actor)? {
        if store
            .lock()
            .unwrap()
            .actors
            .get(&stream)
            .is_some_and(|a| !a.initialized)
        {
            let name = get(call, stream, b"Name")?;
            if name != Value::Nil {
                let name = bytes(call, name)?;
                store
                    .lock()
                    .unwrap()
                    .actors
                    .get_mut(&stream)
                    .unwrap()
                    .load_name = Some(name);
            }
        }
        initialize(call, store, stream)?;
    }
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .initialized = true;
    courses::publish_raw_flag(call, store, actor, "__songlua_init_commands_ran")?;
    Ok(())
}
fn group(call: &mut HostCall<'_>, ids: &[TableId]) -> Result<Value, Error> {
    match ids {
        [] => Ok(Value::Nil),
        [actor] => Ok(Value::Table(*actor)),
        _ => {
            let list = call.try_new_table()?;
            for (i, id) in ids.iter().enumerate() {
                call.raw_table_set(list, Value::Number((i + 1) as f64), Value::Table(*id))?;
            }
            Ok(call.call(helper(call, 3)?, &[Value::Table(list)])?[0])
        }
    }
}
fn invoke_bound(call: &mut HostCall<'_>) -> Result<(), Error> {
    let name = *call.function_data::<&'static str>().unwrap();
    // Production's own adapters close over the receiver. Both colon and dot
    // invocation therefore address this actor, including calls with another
    // table in the receiver slot. settext uniquely always reads argument two.
    let skip = if name == "settext" {
        1
    } else {
        usize::from(matches!(call.arguments().first(), Some(Value::Table(_))))
    };
    let mut args = Vec::with_capacity(call.arguments().len() + 1);
    args.push(call.captures()[2]);
    args.extend(call.arguments().iter().skip(skip).copied());
    call.call_and_return(call.captures()[3], &args)
}

fn actor_name(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<Vec<u8>, Error> {
    let (raw, name) = {
        let guard = store.lock().unwrap();
        let actor = &guard.actors[&actor];
        (
            actor.raw_instance || actor.pending_init || actor.offline_instance,
            actor.state.name.clone(),
        )
    };
    if raw {
        for key in [
            b"__songlua_load_name".as_slice(),
            b"__songlua_native_name",
            b"Name",
        ] {
            let value = get(call, actor, key)?;
            if value != Value::Nil {
                return Ok(assets::text(call, value)?.into_bytes());
            }
        }
        return Ok(Vec::new());
    }
    Ok(name)
}

fn parent_scene(
    call: &mut HostCall<'_>,
    store: &Shared,
    root: TableId,
    parent: Value,
    append: bool,
) -> Result<(), Error> {
    let parent = match parent {
        Value::Nil if !append => None,
        Value::Table(parent) if store.lock().unwrap().actors.contains_key(&parent) => Some(parent),
        _ => return Err(call.error(b"parent must be an actor owned by this runtime")),
    };
    if let Some(parent) = parent {
        {
            let guard = store.lock().unwrap();
            let mut ancestor = Some(parent);
            let mut visited = HashSet::new();
            while let Some(id) = ancestor {
                if id == root || !visited.insert(id) {
                    return Err(call.error(b"actor parent would create a cycle"));
                }
                ancestor = guard.actors.get(&id).and_then(|actor| actor.parent);
            }
            // Before Init, child links exist even though GetParent is still nil.
            let mut descendants = guard.actors[&root].children.clone();
            let mut visited = HashSet::new();
            while let Some(id) = descendants.pop() {
                if id == parent {
                    return Err(call.error(b"actor parent would create a cycle"));
                }
                if visited.insert(id)
                    && let Some(actor) = guard.actors.get(&id)
                {
                    descendants.extend_from_slice(&actor.children);
                }
            }
        }
        if append {
            if !is_frame(store, parent) {
                return Err(call.error(b"ActorFrame parent expected"));
            }
            courses::share_child(call, store, parent, root)?;
            if !store.lock().unwrap().actors[&parent]
                .children
                .contains(&root)
            {
                screen_parts::append(call, store, parent, root)?;
                lifecycle::invalidate_plans(call, store)?;
                return Ok(());
            }
        }
        native_children::adopt(call, store, root, parent)?;
    } else {
        sprites::set(call, root, "__songlua_parent", Value::Nil)?;
        store.lock().unwrap().actors.get_mut(&root).unwrap().parent = None;
    }
    Ok(())
}

fn callback(call: &mut HostCall<'_>) -> Result<(), Error> {
    let Binding { store, op } = call.function_data::<Binding>().unwrap().clone();
    retirement::sweep(&store);
    if matches!(op, Op::Retire) {
        let id = call.number(0)? as u64;
        let retired = retirement::retire(call, &store, id)?;
        return call.push(Value::Boolean(retired));
    }
    if matches!(op, Op::PrepareDefinitions) {
        return offline::install(call, &store);
    }
    if matches!(op, Op::LoadPreparationActor) {
        return loading::load_actor(call, &store);
    }
    if let Op::OfflineConstructor(class) = op {
        return offline::construct(call, &store, class);
    }

    if matches!(op, Op::DiscoverStartup) {
        return capture::discover_startup(call, &store);
    }
    if let Op::Message(op) = op {
        return messages::callback(call, &store, op);
    }
    if matches!(op, Op::End) {
        let id = call.number(0)? as u64;
        if store.lock().unwrap().retired_scenes.contains_key(&id) {
            return call.push(Value::Boolean(false));
        }
        let root = {
            let mut store = store.lock().unwrap();
            let Some(scene) = store.scenes.get_mut(&id) else {
                return call.push(Value::Boolean(false));
            };
            if scene.ended {
                return call.push(Value::Boolean(false));
            }
            // An errored End is still final. The caller observes its partial
            // effects; it must not retry callbacks or advance the outgoing tree.
            scene.ended = true;
            scene.root
        };
        if let Some(root) = root {
            lifecycle::end(call, &store, root)?;
        }
        let actors = store.lock().unwrap().scenes[&id].actors.clone();
        for actor in actors {
            sound::retire(call, &store, actor);
        }
        store
            .lock()
            .unwrap()
            .scenes
            .get_mut(&id)
            .unwrap()
            .sounds_retired = true;
        return call.push(Value::Boolean(true));
    }
    if matches!(
        op,
        Op::Start | Op::Advance | Op::DrawScene | Op::Initialize | Op::SetParent | Op::Append
    ) {
        let id = call.number(0)? as u64;
        if store.lock().unwrap().retired_scenes.contains_key(&id) {
            return call.push(Value::Boolean(false));
        }
        let root = store
            .lock()
            .unwrap()
            .scenes
            .get(&id)
            .map(|scene| (scene.root, scene.ended));
        let Some((root, ended)) = root else {
            return call.push(Value::Boolean(false));
        };
        if ended {
            return Err(call.error(b"cannot advance an ended song Lua scene"));
        }
        if let Some(root) = root {
            if matches!(op, Op::Initialize) {
                prepare_init(&store);
                initialize(call, &store, root)?;
            } else if matches!(op, Op::SetParent | Op::Append) {
                parent_scene(call, &store, root, arg(call, 1), matches!(op, Op::Append))?;
            } else if matches!(op, Op::Start) {
                lifecycle::start(call, &store, root)?;
            } else if matches!(op, Op::DrawScene) {
                draw::scene(call, &store, root)?;
            } else {
                let delta = call.number(1)? as f32;
                lifecycle::advance(call, &store, root, delta)?;
            }
        }
        return call.push(Value::Boolean(true));
    }
    if matches!(op, Op::LoadFont) {
        return text::load_font(call, &store);
    }
    if matches!(op, Op::Template) {
        let declaration = table(call, arg(call, 0))?;
        let globals = table(call, helper(call, 5)?)?;
        for key in ["__songlua_script_dir", "__songlua_song_dir"] {
            if let Some(directory) = assets::field(call, globals, key.as_bytes())? {
                let value = call.try_intern(directory.as_bytes())?;
                sprites::set(call, declaration, key, value)?;
            }
        }
        let id = materialize(call, &store, declaration, Materialization::Template)?;
        let actor = store.lock().unwrap().scenes[&id]
            .root
            .expect("actor template");
        let key = call.try_intern(b"Class")?;
        call.raw_table_set(actor, key, Value::Nil)?;
        return call.push(Value::Table(actor));
    }
    if matches!(op, Op::Instantiate | Op::Construct) {
        let declaration = table(call, arg(call, 0))?;
        let mode = if matches!(op, Op::Instantiate) {
            Materialization::Initialize
        } else {
            Materialization::Construct
        };
        let id = materialize(call, &store, declaration, mode)?;
        return call.push(Value::Number(id as f64));
    }
    if matches!(op, Op::Release) {
        let id = call.number(0)? as u64;
        let removed = release(call, &store, id)?;
        return call.push(Value::Boolean(removed));
    }
    let actor = table(call, arg(call, 0))?;
    if !store.lock().unwrap().actors.contains_key(&actor) {
        return Err(call.error(b"actor instance is not owned by this runtime or has been released"));
    }
    let frame_method = matches!(
        op,
        Op::GetChildren
            | Op::GetChild
            | Op::GetNumChildren
            | Op::Sort
            | Op::OnChildren
            | Op::OnLeaves
            | Op::NamedChildren
            | Op::NamedLeaves
            | Op::Propagate
            | Op::PropagateCommand
    ) || matches!(op, Op::Render(name) if render::FRAME_METHODS.contains(&name))
        || matches!(op, Op::Draw("SetDrawFunction" | "GetDrawFunction"));
    let actor_class = store.lock().unwrap().actors[&actor].state.class;
    let private_child_query = matches!(op, Op::GetChild | Op::GetChildren | Op::GetNumChildren)
        && matches!(
            actor_class,
            "Model" | "OptionRow" | "OptionRowFrame" | "LifeMeter"
        );
    if frame_method && !is_frame(&store, actor) && !private_child_query {
        return Err(call.error(b"ActorFrame expected"));
    }
    match op {
        Op::Lifecycle(operation) => return lifecycle::method(call, &store, actor, operation),
        Op::Render(name) => return render::method(call, &store, actor, name),
        Op::Effect(name) => return effects::method(call, &store, actor, name),
        Op::Wrapper(name) => return wrappers::method(call, &store, actor, name),
        Op::Sound(name) => return sound::method(call, &store, actor, name),
        Op::Sprite(name) => return sprites::method(call, &store, actor, name),
        Op::Banner(name) => return banners::method(call, &store, actor, name),
        Op::Mesh(name) => return meshes::method(call, &store, actor, name),
        Op::CloneTemplate => {
            if store.lock().unwrap().actors[&actor].offline_instance {
                let clone = offline::clone_actor(call, &store, actor, false)?;
                return call.push(Value::Table(clone));
            }
            let id = materialize(call, &store, actor, Materialization::Template)?;
            let root = store.lock().unwrap().scenes[&id].root;
            return call.push(root.map_or(Value::Nil, Value::Table));
        }
        Op::Text(name) => return text::method(call, &store, actor, name),
        Op::Graph(name) => return graphs::method(call, &store, actor, name),
        Op::SongMeter(name) => return song_meters::method(call, &store, actor, name),
        Op::Course(name) => return courses::method(call, &store, actor, name),
        Op::ReadModelPaths => {
            let paths = models::paths(call, actor)?;
            store.lock().unwrap().model_paths_output = paths;
            return Ok(());
        }
        Op::ReadSongMeter => {
            let meter = song_meters::read(call, &store, actor)?;
            store.lock().unwrap().meter_output = meter;
            return Ok(());
        }
        Op::ReadGraph => {
            let graph = graphs::read(call, &store, actor)?;
            store.lock().unwrap().graph_output = Some(graph);
            return Ok(());
        }
        Op::TextDisplay(name) => return text_displays::method(call, &store, actor, name),
        Op::ReadText => {
            let output = text::read(call, actor)?;
            store.lock().unwrap().text_output = Some(output);
            return Ok(());
        }
        Op::Framebuffer(name) => return framebuffers::method(call, &store, actor, name),
        Op::ReadFramebuffer => {
            let framebuffer = framebuffers::read(call, actor)?;
            store.lock().unwrap().framebuffer_output = Some(framebuffer);
            return Ok(());
        }
        Op::Draw(name) => return draw::method(call, &store, actor, name),
        Op::ReadMesh => {
            let mesh = meshes::read(call, actor)?;
            store.lock().unwrap().mesh_output = mesh;
            return Ok(());
        }
        Op::ReadProxy => {
            let target = proxies::read(call, actor)?;
            store.lock().unwrap().proxy_output = target;
            return Ok(());
        }
        Op::GetName if actor_class == "OptionRow" => {
            let bound = get(call, actor, b"__songlua_bound_methods")?;
            let function = get(call, table(call, bound)?, b"GetName")?;
            let args = call.arguments().to_vec();
            return call.call_and_return(function, &args);
        }
        Op::GetName => {
            let name = actor_name(call, &store, actor)?;
            let name = call.try_intern(&name)?;
            return call.push(name);
        }
        Op::Name => {
            let name = bytes(call, arg(call, 1))?;
            let publish = {
                let guard = store.lock().unwrap();
                let actor = &guard.actors[&actor];
                actor.raw_instance || actor.pending_init || actor.offline_instance
            };
            if publish {
                let value = call.try_intern(&name)?;
                let key = call.try_intern(b"__songlua_load_name")?;
                if call.raw_table_get(actor, key)? != Value::Nil {
                    call.raw_table_set(actor, key, value)?;
                }
                let key = call.try_intern(b"__songlua_native_name")?;
                call.raw_table_set(actor, key, value)?;
            }
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&actor)
                .unwrap()
                .state
                .name = name;
        }
        Op::GetParent => {
            let parent = store.lock().unwrap().actors[&actor].parent;
            return call.push(parent.map_or(Value::Nil, Value::Table));
        }
        Op::GetNumChildren => {
            let count = children(call, &store, actor)?.len();
            return call.push(Value::Number(count as f64));
        }
        Op::GetChild if actor_class == "TopScreen" => {
            let bound = get(call, actor, b"__songlua_bound_methods")?;
            let function = get(call, table(call, bound)?, b"GetChild")?;
            if function != Value::Nil {
                let args = call.arguments().to_vec();
                return call.call_and_return(function, &args);
            }
            let key = bytes(call, arg(call, 1))?;
            let map = native_children::named_children(call, actor)?;
            let value = call.with_roots(&[map], |call| {
                let key = call.try_intern(&key)?;
                call.table_get(map, key)
            })?;
            return call.push(value);
        }
        Op::GetChild if has_native_children(&store, actor) => {
            let key = arg(call, 1);
            let key = bytes(call, key)?;
            let map = native_children::named_children(call, actor)?;
            let value = call.with_roots(&[map], |call| {
                let key = call.try_intern(&key)?;
                call.table_get(map, key)
            })?;
            return call.push(value);
        }
        Op::GetChildren if has_native_children(&store, actor) => {
            let result = native_children::named_children(call, actor)?;
            return call.push(result);
        }
        Op::GetChild => {
            let name = bytes(call, arg(call, 1))?;
            let mut ids = Vec::new();
            for id in children(call, &store, actor)? {
                if actor_name(call, &store, id)? == name {
                    ids.push(id);
                }
            }
            let value = group(call, &ids)?;
            return call.push(value);
        }
        Op::GetChildren => {
            let result = Value::Table(call.try_new_table()?);
            return call.with_roots(&[result], |call| {
                let mut names: Vec<(Vec<u8>, Vec<TableId>)> = Vec::new();
                for id in children(call, &store, actor)? {
                    let name = actor_name(call, &store, id)?;
                    if let Some((_, ids)) = names.iter_mut().find(|(n, _)| *n == name) {
                        ids.push(id)
                    } else {
                        names.push((name, vec![id]));
                    }
                }
                for (name, ids) in names {
                    let value = group(call, &ids)?;
                    let key = call.try_intern(&name)?;
                    call.raw_table_set(table(call, result)?, key, value)?;
                }
                call.push(result)
            });
        }
        Op::Sort => sort(call, &store, actor)?,
        Op::Propagate => {
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&actor)
                .unwrap()
                .propagate = !matches!(arg(call, 1), Value::Nil | Value::Boolean(false));
        }
        Op::AddCommand | Op::GetCommand => {
            let name = arg(call, 1);
            if matches!(op, Op::GetCommand) {
                let Some(name) = command_name(call, name) else {
                    return call.push(Value::Nil);
                };
                let value = command(call, actor, &name)?;
                return call.push(value.map_or(Value::Nil, |(function, _)| function));
            }
            let name = bytes(call, name)?;
            std::str::from_utf8(&name).map_err(|_| call.error(b"command name must be UTF-8"))?;
            let value = arg(call, 2);
            if !matches!(value, Value::Function(_) | Value::Native(_)) {
                return Err(call.error(b"function expected"));
            }
            let key = call.try_intern(&[name.as_slice(), b"Command"].concat())?;
            call.table_set(Value::Table(actor), key, value)?;
        }
        Op::PlayCommand | Op::PropagateCommand | Op::NamedChildren | Op::NamedLeaves => {
            let Some(name) = command_name(call, arg(call, 1)) else {
                return call.push(Value::Table(actor));
            };
            let params = call.arguments().get(2).copied();
            match op {
                Op::NamedLeaves => leaves(call, &store, actor, &mut |call, actor| {
                    run_named(call, &store, actor, &name, params)
                })?,
                Op::NamedChildren | Op::PropagateCommand => {
                    for child in children(call, &store, actor)? {
                        play(
                            call,
                            &store,
                            child,
                            &name,
                            params,
                            matches!(op, Op::PropagateCommand),
                        )?;
                    }
                }
                _ => {
                    let propagate = store.lock().unwrap().actors[&actor].propagate;
                    if !propagate {
                        run_named(call, &store, actor, &name, params)?;
                    }
                    for child in children(call, &store, actor)? {
                        play(call, &store, child, &name, params, true)?;
                    }
                }
            }
        }
        Op::Recursive => {
            // The existing production class exposes this name but has no
            // semantic implementation. Migration must preserve that error.
            return Err(call.error(
                b"native actor method RunCommandsRecursively has no semantic implementation",
            ));
        }
        Op::OnChildren | Op::OnLeaves => {
            let function = arg(call, 1);
            if matches!(function, Value::Function(_) | Value::Native(_)) {
                let params = call.arguments().get(2).copied();
                match op {
                    Op::OnLeaves => leaves(call, &store, actor, &mut |call, actor| {
                        run(call, actor, function, None)
                    })?,
                    _ => {
                        for child in children(call, &store, actor)? {
                            run(call, child, function, params)?;
                        }
                    }
                }
            }
        }
        Op::Set(name) => set_scalar(call, &store, actor, name)?,
        Op::Get(name) => return get_scalar(call, &store, actor, name),
        Op::PrepareDefinitions
        | Op::LoadPreparationActor
        | Op::OfflineConstructor(_)
        | Op::Instantiate
        | Op::Construct
        | Op::Initialize
        | Op::SetParent
        | Op::Append
        | Op::DiscoverStartup
        | Op::Template
        | Op::LoadFont
        | Op::Release
        | Op::Retire
        | Op::Start
        | Op::Advance
        | Op::End
        | Op::DrawScene
        | Op::Message(_) => {
            unreachable!()
        }
    }
    call.push(Value::Table(actor))
}
fn command_name(call: &HostCall<'_>, value: Value) -> Option<Vec<u8>> {
    let Value::String(id) = value else {
        return None;
    };
    std::str::from_utf8(call.string_bytes(id)?)
        .ok()
        .map(|name| name.as_bytes().to_vec())
}
fn set_scalar(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    if name == "draworder" {
        if let Some(value) = integer_scalar(call, arg(call, 1)) {
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&actor)
                .unwrap()
                .state
                .draw_order = value;
            let key = call.try_intern(b"__songlua_state_draw_order")?;
            call.raw_table_set(actor, key, Value::Number(value as f64))?;
            capture::property(store, actor, name);
        }
        return Ok(());
    }
    let allows_nonfinite = matches!(
        name,
        "x" | "y" | "zoom" | "zoomx" | "zoomy" | "zoomz" | "rotationx" | "rotationy" | "rotationz"
    );
    if name == "xy" {
        let store_ref = store;
        let x = float_scalar(call, arg(call, 1), false);
        let y = float_scalar(call, arg(call, 2), false);
        let mut store = store.lock().unwrap();
        let position = store.actors.get_mut(&actor).unwrap().destination_mut();
        if let Some(x) = x {
            position.x = x;
        }
        if let Some(y) = y {
            position.y = y;
        }
        drop(store);
        capture::write(
            store_ref,
            actor,
            crate::SongLuaOverlayStateDelta {
                x,
                y,
                ..Default::default()
            },
            false,
        );
        song_replay::publish_scalar(call, store_ref, actor, name)?;
        return Ok(());
    }
    let first = if name == "visible" {
        let Some(value) = boolish(call, arg(call, 1)) else {
            return Ok(());
        };
        value as u8 as f32
    } else {
        let Some(value) = float_scalar(call, arg(call, 1), allows_nonfinite) else {
            return Ok(());
        };
        value
    };
    let second = if name == "setsize" {
        let Some(value) = float_scalar(call, arg(call, 2), false) else {
            return Ok(());
        };
        value
    } else {
        0.
    };
    if matches!(name, "SetWidth" | "SetHeight") {
        sprites::refresh_size(call, store, actor)?;
    }
    if matches!(name, "SetWidth" | "SetHeight" | "setsize") {
        let size = {
            let store = store.lock().unwrap();
            let actor = &store.actors[&actor];
            (actor.state.class == "ActorFrameTexture").then(|| match name {
                "SetWidth" => [first, actor.state.size[1].abs()],
                "SetHeight" => [actor.state.size[0].abs(), first],
                _ => [first, second],
            })
        };
        if let Some(size) = size {
            let value = sprites::vector_value(call, &size)?;
            let key = call.try_intern(b"__songlua_state_size")?;
            call.raw_table_set(actor, key, value)?;
        }
    }
    if name == "visible" {
        sprites::set(
            call,
            actor,
            "__songlua_visible",
            Value::Boolean(first != 0.),
        )?;
    }
    let preparation = {
        let store = store.lock().unwrap();
        !store.playback || store.actors[&actor].replay.is_some()
    };
    let captured_position = if preparation && matches!(name, "addx" | "addy" | "addz") {
        text::captured_position(call, actor, &name[3..])?
    } else {
        None
    };
    let id = actor;
    let mut guard = store.lock().unwrap();
    let actor = guard.actors.get_mut(&id).unwrap();
    let captured_position = captured_position.or_else(|| {
        actor.replay.as_ref().and_then(|_| {
            let pose = actor.getter_destination();
            match name {
                "addx" => Some(pose.x),
                "addy" => Some(pose.y),
                "addz" => Some(pose.z),
                _ => None,
            }
        })
    });
    let immediate = &mut actor.state;
    match name {
        "SetWidth" => immediate.size = [first, immediate.size[1].abs()],
        "SetHeight" => immediate.size = [immediate.size[0].abs(), first],
        "setsize" => immediate.size = [first, second],
        "visible" => immediate.visible = first != 0.,
        _ => {}
    }
    if matches!(name, "SetWidth" | "SetHeight" | "setsize") {
        immediate.render.size = Some(immediate.size);
    }
    let s = actor.destination_mut();
    match name {
        "x" => s.x = first,
        "y" => s.y = first,
        "z" => s.z = first,
        "addx" => s.x = captured_position.unwrap_or(s.x) + first,
        "addy" => s.y = captured_position.unwrap_or(s.y) + first,
        "addz" => s.z = captured_position.unwrap_or(s.z) + first,
        "zoom" => {
            s.zoom = first;
            s.zoom_x = first;
            s.zoom_y = first;
            s.zoom_z = first;
        }
        "zoomx" => s.zoom_x = first,
        "zoomy" => s.zoom_y = first,
        "zoomz" => s.zoom_z = first,
        "rotationx" => s.rot_x_deg = first,
        "rotationy" => s.rot_y_deg = first,
        "rotationz" => s.rot_z_deg = first,
        "addrotationx" => s.rot_x_deg += first,
        "addrotationy" => s.rot_y_deg += first,
        "addrotationz" => s.rot_z_deg += first,
        "aux" => s.aux = first,
        "SetWidth" | "SetHeight" | "setsize" | "visible" => {}
        _ => unreachable!(),
    }
    match name {
        "rotationx" | "addrotationx" => actor.state.rotation[0] = actor.destination().rot_x_deg,
        "rotationy" | "addrotationy" => actor.state.rotation[1] = actor.destination().rot_y_deg,
        "rotationz" | "addrotationz" => actor.state.rotation[2] = actor.destination().rot_z_deg,
        _ => {}
    }
    let template_position = if actor.offline_template {
        match name {
            "x" | "addx" => Some(("x", actor.destination().x)),
            "y" | "addy" => Some(("y", actor.destination().y)),
            "z" | "addz" => Some(("z", actor.destination().z)),
            _ => None,
        }
    } else {
        None
    };
    drop(guard);
    capture::property(store, id, name);
    if let Some((axis, value)) = template_position {
        text::capture_template_position(call, id, axis, value)?;
    }
    if matches!(name, "zoom" | "zoomx" | "zoomy") {
        text::pre_zoom(call, store, id, name != "zoomy", name != "zoomx")?;
    }
    song_replay::publish_scalar(call, store, id, name)
}
fn float_scalar(call: &HostCall<'_>, value: Value, allows_nonfinite: bool) -> Option<f32> {
    match value {
        Value::Number(value) => {
            let value = value as f32;
            (allows_nonfinite || value.is_finite()).then_some(value)
        }
        Value::String(id) => std::str::from_utf8(call.string_bytes(id)?)
            .ok()?
            .trim()
            .parse()
            .ok(),
        _ => None,
    }
}
fn integer_scalar(call: &HostCall<'_>, value: Value) -> Option<i32> {
    match value {
        Value::Number(value) if value.is_finite() => Some(value.round() as i32),
        Value::String(id) => {
            let text = std::str::from_utf8(call.string_bytes(id)?).ok()?.trim();
            text.parse()
                .ok()
                .or_else(|| text.parse::<f32>().ok().map(|value| value.round() as i32))
        }
        _ => None,
    }
}
fn boolish(call: &HostCall<'_>, value: Value) -> Option<bool> {
    match value {
        Value::Boolean(value) => Some(value),
        Value::Number(value) => Some(value != 0.0),
        Value::String(id) => {
            let text = std::str::from_utf8(call.string_bytes(id)?).ok()?.trim();
            if ["true", "yes", "on"]
                .iter()
                .any(|word| text.eq_ignore_ascii_case(word))
            {
                Some(true)
            } else if ["false", "no", "off"]
                .iter()
                .any(|word| text.eq_ignore_ascii_case(word))
            {
                Some(false)
            } else {
                text.parse::<f32>().ok().map(|value| value != 0.0)
            }
        }
        _ => None,
    }
}
fn get_scalar(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    if matches!(
        name,
        "GetWidth" | "GetHeight" | "GetZoomedWidth" | "GetZoomedHeight"
    ) {
        sprites::refresh_size(call, store, actor)?;
    }
    let store = store.lock().unwrap();
    let actor = &store.actors[&actor];
    let s = &actor.state;
    let current = &actor.current;
    let getters =
        actor
            .preparation_getters
            .unwrap_or([current.x, current.y, current.z, current.aux]);
    let dest = actor.getter_destination();
    let value = match name {
        "GetX" => getters[0],
        "GetY" => getters[1],
        "GetZ" => getters[2],
        "GetDestX" => dest.x,
        "GetDestY" => dest.y,
        "GetDestZ" => dest.z,
        "GetZoom" | "GetZoomX" => dest.zoom_x,
        "GetZoomY" => dest.zoom_y,
        "GetZoomZ" => dest.zoom_z,
        "GetRotationX" => s.rotation[0],
        "GetRotationY" => s.rotation[1],
        "GetRotationZ" => s.rotation[2],
        "GetWidth" => s.size[0].abs(),
        "GetHeight" => s.size[1].abs(),
        "GetZoomedWidth" => s.size[0].abs() * (s.render.basezoom_x * dest.zoom_x),
        "GetZoomedHeight" => s.size[1].abs() * (s.render.basezoom_y * dest.zoom_y),
        "getaux" => getters[3],
        "GetVisible" => return call.push(Value::Boolean(s.visible)),
        _ => unreachable!(),
    };
    call.push(Value::Number(f64::from(value)))
}

//! Constructor and startup command capture, before compiler frame replay.
//! This is song-host scheduling state, not part of the Lua interpreter.
use super::*;
use crate::{SongLuaOverlayCommandBlock as Block, SongLuaOverlayStateDelta as Delta};

/// Owned command output and queue metadata for preparation/baking. These values
/// retain no Lua handles. Step zero denotes direct or immediate capture output.
#[derive(Clone, Debug, PartialEq)]
pub struct ActorCommandCapture {
    pub blocks: Vec<Block>,
    pub block_steps: Vec<usize>,
    /// A command occupies a zero-duration queue state, represented by None.
    pub steps: Vec<Option<f32>>,
    pub queued_commands: Vec<(Vec<u8>, f32)>,
}

#[derive(Clone)]
struct Entry {
    block: Block,
    tween_step: usize,
}

#[derive(Clone)]
struct Spin {
    current: [f32; 3],
    queued: bool,
}

#[derive(Clone, Default)]
pub(super) struct Capture {
    cursor: f32,
    pub(super) time_left: f32,
    current: Option<Entry>,
    blocks: Vec<Entry>,
    // Finish replaces the block list without replacing native's cached
    // immediate block. None as the index represents that detached block.
    immediate: Option<(f32, Option<usize>)>,
    steps: VecDeque<Option<f32>>,
    pending: VecDeque<(Vec<u8>, f32)>,
    /// A self-queue describes a repeating command; it must not recurse during
    /// discovery. Frame scheduling will consume this retained command later.
    pub(super) recurring: Option<(Vec<u8>, f32, f32)>,
    active_start: f32,
    spin: Option<Spin>,
    deferred: bool,
}

fn block(start: f32, duration: f32, easing: Option<String>, queued: bool) -> Block {
    Block {
        progress: None,
        queued,
        start,
        duration,
        easing,
        opt1: None,
        opt2: None,
        delta: Delta::default(),
    }
}

impl Capture {
    pub(super) fn begin_discovery(&mut self) {
        self.flush();
        self.blocks.clear();
        self.immediate = None;
    }

    pub(super) fn snapshot(&mut self) -> ActorCommandCapture {
        let blocks = self.blocks();
        ActorCommandCapture {
            blocks,
            block_steps: self.blocks.iter().map(|entry| entry.tween_step).collect(),
            steps: self.steps.iter().copied().collect(),
            queued_commands: self.pending.iter().cloned().collect(),
        }
    }

    pub(super) fn pending_steps(&self) -> usize {
        self.steps.len()
    }

    fn scheduled(&self) -> bool {
        self.cursor.max(0.) > f32::EPSILON
            || self
                .current
                .as_ref()
                .is_some_and(|entry| entry.block.duration.max(0.) > f32::EPSILON)
    }

    fn cancel(&mut self, finish: bool) {
        self.flush();
        if finish {
            let mut delta = Delta::default();
            for entry in &self.blocks {
                crate::merge_overlay_delta(&mut delta, &entry.block.delta);
            }
            self.blocks.clear();
            if !crate::overlay_delta_is_empty(&delta) {
                let mut final_block = block(0., 0., None, false);
                final_block.delta = delta;
                self.blocks.push(Entry {
                    block: final_block,
                    tween_step: 0,
                });
            }
            self.immediate = self.immediate.map(|(start, _)| (start, None));
        } else {
            self.blocks
                .retain(|entry| entry.tween_step == 0 && entry.block.duration == 0.);
            self.immediate = None;
        }
        self.cursor = 0.;
        self.time_left = 0.;
        self.steps.clear();
        self.pending.clear();
        self.recurring = None;
        self.deferred = false;
    }

    pub(super) fn hurry(&mut self, factor: f32) {
        self.flush();
        for entry in &mut self.blocks {
            entry.block.start *= factor;
            entry.block.duration *= factor;
        }
        for seconds in self.steps.iter_mut().flatten() {
            *seconds *= factor;
        }
        self.cursor *= factor;
        self.time_left *= factor;
        if let Some((start, Some(_))) = &mut self.immediate {
            *start *= factor;
        }
        // Queue dispatch starts are separate from the scaled tween clocks;
        // the production constructor retains those original starts as well.
    }

    fn current(&mut self, queued: bool) -> &mut Entry {
        self.current.get_or_insert_with(|| Entry {
            block: block(self.cursor, 0., None, queued),
            tween_step: self.steps.len(),
        })
    }

    pub(super) fn flush(&mut self) {
        if let Some(entry) = self.current.take() {
            self.cursor = entry.block.start + entry.block.duration.max(0.);
            if !crate::overlay_delta_is_empty(&entry.block.delta) {
                self.blocks.push(entry);
            }
        }
    }

    pub(super) fn begin_tween(&mut self, duration: f32, easing: &str, queued: bool) {
        self.flush();
        if let Some(spin) = &mut self.spin {
            spin.queued = true;
        }
        self.steps.push_back(Some(duration));
        self.time_left = self.cursor + duration;
        self.current = Some(Entry {
            block: block(self.cursor, duration, Some(easing.to_owned()), queued),
            tween_step: self.steps.len(),
        });
    }

    pub(super) fn write(&mut self, delta: Delta, immediate: bool, scope: Option<f32>) {
        let start = scope.unwrap_or(0.);
        let direct = start == 0.
            && self.cursor == 0.
            && self.current.as_ref().is_none_or(|c| c.block.duration == 0.)
            && self.steps.is_empty();
        let target = if !immediate || direct {
            &mut self.current(scope.is_some()).block.delta
        } else {
            let index = if let Some((_, index)) = self
                .immediate
                .filter(|(cached, _)| (*cached - start).abs() <= f32::EPSILON)
            {
                let Some(index) = index else { return };
                index
            } else {
                let index = self
                    .blocks
                    .iter()
                    .position(|entry| {
                        entry.block.start > start
                            || (entry.block.start == start
                                && (entry.tween_step > 0 || entry.block.duration > 0.))
                    })
                    .unwrap_or(self.blocks.len());
                self.blocks.insert(
                    index,
                    Entry {
                        block: block(start, 0., None, scope.is_some()),
                        tween_step: 0,
                    },
                );
                self.immediate = Some((start, Some(index)));
                index
            };
            &mut self.blocks[index].block.delta
        };
        crate::merge_overlay_delta(target, &delta);
    }

    pub(super) fn blocks(&mut self) -> Vec<Block> {
        self.flush();
        self.blocks
            .iter()
            .map(|entry| {
                let mut block = entry.block.clone();
                block.duration = block.duration.max(0.);
                block
            })
            .collect()
    }
}

pub(super) fn write(store: &Shared, actor: TableId, delta: Delta, immediate: bool) {
    let mut guard = store.lock().unwrap();
    let scope = guard.capture_scope;
    if let Some(actor) = guard.actors.get_mut(&actor) {
        record(actor, delta, immediate, scope);
    }
}

fn record(actor: &mut Actor, delta: Delta, immediate: bool, scope: Option<f32>) {
    if let Some(replay) = &mut actor.replay {
        for target in crate::tween_pose::TARGETS {
            if delta.has_update_target(target) {
                replay.targets |= 1u128 << target as usize;
            }
        }
    }
    if let Some(pose) = actor
        .replay
        .as_mut()
        .and_then(|replay| replay.getters.as_mut())
    {
        let mut state = crate::SongLuaOverlayState::default();
        pose.write_to(&mut state);
        crate::apply_overlay_delta(&mut state, &delta);
        *pose = state.into();
    }
    if actor.replay.is_some() {
        let current = actor.current;
        if let Some(getters) = &mut actor.preparation_getters {
            for ((getter, changed), value) in getters
                .iter_mut()
                .zip([delta.x, delta.y, delta.z, delta.aux])
                .zip([current.x, current.y, current.z, current.aux])
            {
                if changed.is_some() {
                    *getter = value;
                }
            }
        }
    }
    let Some(capture) = &mut actor.capture else {
        return;
    };
    if let Some(spin) = &mut capture.spin
        && !spin.queued
    {
        for (axis, value) in
            spin.current
                .iter_mut()
                .zip([delta.rot_x_deg, delta.rot_y_deg, delta.rot_z_deg])
        {
            if let Some(value) = value {
                *axis = value;
            }
        }
    }
    // Zero-duration construction steps do not defer current-position getters.
    // These fields are independent of the retained destination/spin queue.
    if !capture.scheduled() {
        let values = [delta.x, delta.y, delta.z, delta.aux];
        if values.iter().any(Option::is_some) {
            let current = actor.current;
            let getters = actor.preparation_getters.get_or_insert([
                current.x,
                current.y,
                current.z,
                current.aux,
            ]);
            for (getter, value) in getters.iter_mut().zip(values) {
                if let Some(value) = value {
                    *getter = value;
                }
            }
        }
    }
    capture.write(delta, immediate, scope);
}

pub(super) fn cancel(actor: &mut Actor, finish: bool) -> bool {
    if actor.capture.is_none() {
        return false;
    }
    let current = actor.current;
    let getters =
        actor
            .preparation_getters
            .unwrap_or([current.x, current.y, current.z, current.aux]);
    let mut dest = *actor.destination();
    if !finish {
        [dest.x, dest.y, dest.z] = [getters[0], getters[1], getters[2]];
    }
    if let Some(spin) = &mut actor.capture.as_mut().unwrap().spin {
        if finish {
            spin.current = [dest.rot_x_deg, dest.rot_y_deg, dest.rot_z_deg];
        }
        [dest.rot_x_deg, dest.rot_y_deg, dest.rot_z_deg] = spin.current;
        spin.queued = false;
    }
    actor.capture.as_mut().unwrap().cancel(finish);
    actor.current = dest;
    actor.queue.clear();
    actor.sync_rotation_getters();
    actor.preparation_getters = Some(getters);
    true
}

pub(super) fn start_spin(actor: &mut Actor) {
    let pose = *actor.destination();
    if let Some(capture) = &mut actor.capture {
        capture.spin.get_or_insert(Spin {
            current: [pose.rot_x_deg, pose.rot_y_deg, pose.rot_z_deg],
            queued: false,
        });
    }
}

/// Record an actual successful write, including writes equal to the old value.
/// Comparing snapshots would lose those writes and change later composition.
pub(super) fn property(store: &Shared, id: TableId, name: &str) {
    let mut guard = store.lock().unwrap();
    let scope = guard.capture_scope;
    let immediate_visibility =
        scope.is_some() || guard.startup_queues.is_some() || guard.startup_discovery;
    let actor = guard.actors.get_mut(&id).unwrap();
    if actor.capture.is_none() && actor.replay.is_none() {
        return;
    }
    let pose = actor.destination();
    let state = &actor.state;
    let render = &state.render;
    let mut delta = Delta::default();
    let mut immediate = false;
    match name {
        "x" | "addx" | "CenterX" => delta.x = Some(pose.x),
        "y" | "addy" | "CenterY" => delta.y = Some(pose.y),
        "z" | "addz" => delta.z = Some(pose.z),
        "Center" => {
            delta.x = Some(pose.x);
            delta.y = Some(pose.y);
        }
        "zoom" => {
            delta.zoom = Some(pose.zoom);
            delta.zoom_x = Some(pose.zoom_x);
            delta.zoom_y = Some(pose.zoom_y);
            delta.zoom_z = Some(pose.zoom_z);
        }
        "zoomx" | "zoomtowidth" => delta.zoom_x = Some(pose.zoom_x),
        "zoomy" | "zoomtoheight" => delta.zoom_y = Some(pose.zoom_y),
        "zoomz" => delta.zoom_z = Some(pose.zoom_z),
        "zoomto" => {
            delta.zoom_x = Some(pose.zoom_x);
            delta.zoom_y = Some(pose.zoom_y);
        }
        "stretchto" => {
            delta.x = Some(pose.x);
            delta.y = Some(pose.y);
            delta.zoom_x = Some(pose.zoom_x);
            delta.zoom_y = Some(pose.zoom_y);
        }
        "rotationx" | "addrotationx" => delta.rot_x_deg = Some(pose.rot_x_deg),
        "rotationy" | "addrotationy" => delta.rot_y_deg = Some(pose.rot_y_deg),
        "rotationz" | "addrotationz" => delta.rot_z_deg = Some(pose.rot_z_deg),
        "aux" => delta.aux = Some(pose.aux),
        "visible" => {
            delta.visible = Some(state.visible);
            immediate = immediate_visibility;
        }
        "draworder" => delta.draw_order = Some(state.draw_order),
        "size" | "SetWidth" | "SetHeight" | "setsize" => {
            delta.size = Some(state.size);
            immediate = true;
        }
        "diffuse" | "diffusecolor" | "diffusealpha" => delta.diffuse = Some(pose.diffuse),
        "glow" => delta.glow = Some(pose.glow),
        "vertex_colors" => delta.vertex_colors = pose.vertex_colors,
        "cropleft" => delta.cropleft = Some(pose.cropleft),
        "cropright" => delta.cropright = Some(pose.cropright),
        "croptop" => delta.croptop = Some(pose.croptop),
        "cropbottom" => delta.cropbottom = Some(pose.cropbottom),
        "fadeleft" => delta.fadeleft = Some(pose.fadeleft),
        "faderight" => delta.faderight = Some(pose.faderight),
        "fadetop" => delta.fadetop = Some(pose.fadetop),
        "fadebottom" => delta.fadebottom = Some(pose.fadebottom),
        "skewx" => delta.skew_x = Some(pose.skew_x),
        "skewy" => delta.skew_y = Some(pose.skew_y),
        "heading" | "pitch" | "roll" => delta.quaternion = Some(pose.quaternion),
        "halign" => delta.halign = Some(render.halign),
        "valign" => delta.valign = Some(render.valign),
        // Immediate renderer/base-transform properties do not join a tween.
        "basealpha" => {
            delta.base_alpha = Some(render.base_alpha);
            immediate = true;
        }
        "basezoom" => {
            delta.basezoom = Some(render.basezoom);
            delta.basezoom_x = Some(render.basezoom_x);
            delta.basezoom_y = Some(render.basezoom_y);
            delta.basezoom_z = Some(render.basezoom_z);
            immediate = true;
        }
        "basezoomx" => {
            delta.basezoom_x = Some(render.basezoom_x);
            immediate = true;
        }
        "basezoomy" => {
            delta.basezoom_y = Some(render.basezoom_y);
            immediate = true;
        }
        "basezoomz" => {
            delta.basezoom_z = Some(render.basezoom_z);
            immediate = true;
        }
        "baserotationx" | "baserotationy" | "baserotationz" => {
            delta.base_rotation = Some(render.base_rotation);
            immediate = true;
        }
        "shadowlength" | "shadowlengthx" | "shadowlengthy" => {
            delta.shadow_len = Some(render.shadow_len);
            immediate = true;
        }
        "shadowcolor" => {
            delta.shadow_color = Some(render.shadow_color);
            immediate = true;
        }
        "zbias" => {
            delta.z_bias = Some(render.z_bias);
            immediate = true;
        }
        "fov" => {
            delta.fov = render.fov;
            immediate = true;
        }
        _ => return,
    }
    record(actor, delta, immediate, scope);
}

pub(super) fn queue(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: Vec<u8>,
) -> Result<bool, Error> {
    let mut command_field = name.clone();
    command_field.extend_from_slice(b"Command");
    let overflow = {
        let guard = store.lock().unwrap();
        let actor = &guard.actors[&actor];
        !actor.active_commands.contains(&command_field)
            && actor
                .capture
                .as_ref()
                .is_some_and(|capture| capture.pending_steps() > 50)
    };
    if overflow {
        lifecycle::finish(call, store, actor)?;
    }
    let drain = {
        let mut guard = store.lock().unwrap();
        let startup = guard.startup_queues.is_some();
        let actor = guard.actors.get_mut(&actor).unwrap();
        let Some(capture) = &mut actor.capture else {
            return Ok(false);
        };
        capture.flush();
        let mut field = name.clone();
        field.extend_from_slice(b"Command");
        if actor.active_commands.contains(&field) {
            capture.recurring = Some((
                name,
                capture.active_start,
                (capture.cursor - capture.active_start).max(0.),
            ));
            return Ok(true);
        }
        capture.steps.push_back(None);
        capture.pending.push_back((name, capture.cursor));
        startup || actor.active_commands.is_empty()
    };
    if drain {
        drain_commands(call, store, actor)?;
    }
    Ok(true)
}

pub(super) fn drain_commands(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    {
        let mut guard = store.lock().unwrap();
        let pending = guard
            .actors
            .get(&actor)
            .and_then(|actor| actor.capture.as_ref())
            .is_some_and(|capture| !capture.pending.is_empty());
        if let Some(queued) = &mut guard.startup_queues {
            if pending && !queued.contains(&actor) {
                queued.push(actor);
            }
            return Ok(());
        }
    }
    loop {
        let next = {
            let mut guard = store.lock().unwrap();
            let discovery = guard.startup_discovery;
            let Some(capture) = guard
                .actors
                .get_mut(&actor)
                .and_then(|a| a.capture.as_mut())
            else {
                return Ok(());
            };
            let Some((name, start)) = capture.pending.front() else {
                return Ok(());
            };
            if (discovery || capture.deferred) && (name.starts_with(b"!") || *start > 0.) {
                capture.deferred = true;
                return Ok(());
            }
            let next = capture.pending.pop_front().unwrap();
            while let Some(step) = capture.steps.pop_front() {
                if step.is_none() {
                    break;
                }
            }
            next
        };
        let (name, start) = next;
        let prior = store.lock().unwrap().capture_scope.replace(start);
        // The registry and this lexical root retain the dispatch target even
        // when its command edits the scene and forces a collection.
        let result = call.with_roots(&[Value::Table(actor)], |call| {
            if let Some(message) = name.strip_prefix(b"!") {
                messages::queued(call, store, message)
            } else {
                let mut field = name.clone();
                field.extend_from_slice(b"Command");
                let previous = store
                    .lock()
                    .unwrap()
                    .actors
                    .get_mut(&actor)
                    .unwrap()
                    .active_commands
                    .remove(&field);
                let result = dispatch(call, store, actor, &name);
                if previous {
                    store
                        .lock()
                        .unwrap()
                        .actors
                        .get_mut(&actor)
                        .unwrap()
                        .active_commands
                        .insert(field);
                }
                result
            }
        });
        store.lock().unwrap().capture_scope = prior;
        result?;
    }
}

fn dispatch(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &[u8],
) -> Result<(), Error> {
    {
        let mut guard = store.lock().unwrap();
        let start = guard.capture_scope.unwrap_or(0.);
        if let Some(capture) = guard
            .actors
            .get_mut(&actor)
            .and_then(|a| a.capture.as_mut())
            && capture.cursor < start
        {
            capture.flush();
            capture.cursor = start;
        }
    }
    native_children::run_command(call, store, actor, name, None)?;
    let kind = sprites::field(call, actor, "__songlua_actor_type")?;
    if matches!(kind, Value::String(id) if matches!(call.string_bytes(id), Some(b"ActorFrame" | b"ActorFrameTexture" | b"TopScreen")))
    {
        native_children::with_children(call, actor, |call, child| {
            dispatch(call, store, child, name)
        })?;
    }
    Ok(())
}

pub(super) fn command_start(store: &Shared, actor: TableId) -> Option<f32> {
    let mut guard = store.lock().unwrap();
    let capture = guard.actors.get_mut(&actor)?.capture.as_mut()?;
    Some(std::mem::replace(&mut capture.active_start, capture.cursor))
}

pub(super) fn command_end(store: &Shared, actor: TableId, previous: Option<f32>) {
    if let Some(previous) = previous
        && let Some(capture) = store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .and_then(|a| a.capture.as_mut())
    {
        capture.active_start = previous;
    }
}

impl Actors {
    pub(in crate::rust_engine) fn begin_preparation(&self, vm: &mut Vm) -> Result<bool, Error> {
        {
            let guard = self.store.lock().unwrap();
            if guard.preparing
                || guard.playback
                || guard.clock.live.load(std::sync::atomic::Ordering::Relaxed)
            {
                return Ok(false);
            }
        }
        let function = vm.rooted(self.prepare_definitions)?;
        vm.call(function, &[])?;
        let mut guard = self.store.lock().unwrap();
        guard.preparing = true;
        guard.constructing_capture = true;
        Ok(true)
    }

    pub(in crate::rust_engine) fn discover_startup(&self, vm: &mut Vm) -> Result<(), Error> {
        let function = vm.rooted(self.discover_startup)?;
        vm.call(function, &[])?;
        Ok(())
    }

    pub(super) fn discover_queued(&self, vm: &mut Vm, queued: Vec<TableId>) -> Result<(), Error> {
        let mut roots = vec![Value::Table(self.registry), Value::Table(self.helpers)];
        roots.extend(queued.iter().copied().map(Value::Table));
        let function = vm.new_host_function_with_data(
            |call| {
                let (store, queued) = call
                    .function_data::<(Shared, Vec<TableId>)>()
                    .unwrap()
                    .clone();
                run_discovery(call, &store, queued)
            },
            &roots,
            (self.store.clone(), queued),
        )?;
        vm.call(function, &[])?;
        Ok(())
    }

    pub(in crate::rust_engine) fn command_capture(
        &self,
        actor: Value,
    ) -> Option<ActorCommandCapture> {
        let Value::Table(actor) = actor else {
            return None;
        };
        let mut guard = self.store.lock().unwrap();
        let capture = guard.actors.get_mut(&actor)?.capture.as_mut()?;
        Some(capture.snapshot())
    }

    pub(in crate::rust_engine) fn captured_blocks(&self, actor: Value) -> Option<Vec<Block>> {
        let Value::Table(actor) = actor else {
            return None;
        };
        let mut guard = self.store.lock().unwrap();
        Some(guard.actors.get_mut(&actor)?.capture.as_mut()?.blocks())
    }
}

pub(super) fn discover_startup(call: &mut HostCall<'_>, store: &Shared) -> Result<(), Error> {
    let queued = store.lock().unwrap().startup_queues.take();
    let Some(queued) = queued else {
        return Ok(());
    };
    run_discovery(call, store, queued)
}

fn run_discovery(
    call: &mut HostCall<'_>,
    store: &Shared,
    queued: Vec<TableId>,
) -> Result<(), Error> {
    let previous = std::mem::replace(&mut store.lock().unwrap().startup_discovery, true);
    let roots = queued.iter().copied().map(Value::Table).collect::<Vec<_>>();
    let result = call.with_roots(&roots, |call| {
        for actor in queued {
            drain_commands(call, store, actor)?;
        }
        Ok(())
    });
    store.lock().unwrap().startup_discovery = previous;
    result
}

//! Existing actor queue and frame lifecycle, owned by the song host.
use super::*;

pub(super) struct TweenStep {
    index: Option<usize>,
    duration: f32,
    left: f32,
    from: Option<TweenPose>,
    pub(super) to: TweenPose,
    easing: String,
    opt1: Option<f32>,
    command: Option<Vec<u8>>,
}

impl TweenStep {
    pub(super) fn startup(
        index: usize,
        duration: f32,
        to: TweenPose,
        easing: Option<String>,
        opt1: Option<f32>,
        command: Option<Vec<u8>>,
    ) -> Self {
        Self {
            index: Some(index),
            duration,
            left: duration,
            from: None,
            to,
            easing: easing.unwrap_or_default(),
            opt1,
            command,
        }
    }
}

#[derive(Clone, Copy)]
pub(super) enum Lifecycle {
    Ease(&'static str),
    Tween,
    Sleep,
    Hibernate,
    Stop,
    Finish,
    Hurry,
    TimeLeft,
    Queue,
    QueueMessage,
    Update,
    Rate,
    GetRate,
}

pub(super) const ACTOR_METHODS: &[(&str, Lifecycle)] = &[
    ("linear", Lifecycle::Ease("linear")),
    ("accelerate", Lifecycle::Ease("inQuad")),
    ("decelerate", Lifecycle::Ease("outQuad")),
    ("smooth", Lifecycle::Ease("smooth")),
    ("spring", Lifecycle::Ease("spring")),
    ("bouncebegin", Lifecycle::Ease("bouncebegin")),
    ("bounceend", Lifecycle::Ease("bounceend")),
    ("tween", Lifecycle::Tween),
    ("sleep", Lifecycle::Sleep),
    ("hibernate", Lifecycle::Hibernate),
    ("stoptweening", Lifecycle::Stop),
    ("finishtweening", Lifecycle::Finish),
    ("hurrytweening", Lifecycle::Hurry),
    ("GetTweenTimeLeft", Lifecycle::TimeLeft),
    ("queuecommand", Lifecycle::Queue),
    ("queuemessage", Lifecycle::QueueMessage),
];
pub(super) const FRAME_METHODS: &[(&str, Lifecycle)] = &[
    ("SetUpdateFunction", Lifecycle::Update),
    ("SetUpdateRate", Lifecycle::Rate),
    ("GetUpdateRate", Lifecycle::GetRate),
];

pub(super) fn finish(call: &mut HostCall<'_>, store: &Shared, id: TableId) -> Result<(), Error> {
    {
        let mut store = store.lock().unwrap();
        let actor = store.actors.get_mut(&id).unwrap();
        if !capture::cancel(actor, true) {
            if let Some(last) = actor.queue.back() {
                actor.current = last.to;
            }
            actor.queue.clear();
            actor.sync_rotation_getters();
        }
    }
    song_replay::sync_getters(call, store, id)?;
    // Finish also visits native named children. Hurry, TimeLeft and ordinary
    // frame updates retain the production traversal of authored children only.
    for child in children(call, store, id)? {
        finish(call, store, child)?;
    }
    Ok(())
}

fn hurry(store: &mut Store, id: TableId, factor: f32) {
    let actor = store.actors.get_mut(&id).unwrap();
    for step in &mut actor.queue {
        step.duration *= factor;
        step.left *= factor;
    }
    if let Some(capture) = &mut actor.capture {
        capture.hurry(factor);
    }
    for child in actor.children.clone() {
        hurry(store, child, factor);
    }
}

pub(super) fn time_left(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
) -> Result<f32, Error> {
    call.with_roots(&[Value::Table(id)], |call| {
        if let Some(state) = transitions::state(call, id)? {
            return if state == 1 {
                match transitions::child(call, id)? {
                    Some(child) => time_left(call, store, child),
                    None => Ok(0.),
                }
            } else {
                Ok(0.)
            };
        }
        let theme_hibernating = !matches!(
            get(call, id, b"__songlua_theme_hibernating")?,
            Value::Nil | Value::Boolean(false)
        );
        let native = {
            let store = store.lock().unwrap();
            store.actors.get(&id).map(|actor| {
                let hibernate = if theme_hibernating {
                    f32::INFINITY
                } else {
                    actor.hibernate
                };
                (
                    hibernate,
                    actor.capture.as_ref().map_or_else(
                        || {
                            actor
                                .queue
                                .iter()
                                .fold(hibernate, |left, step| left + step.left)
                        },
                        |capture| hibernate + capture.time_left.max(0.),
                    ),
                )
            })
        };
        let (hibernate, mut left) = if let Some(native) = native {
            native
        } else {
            let value = get(call, id, b"__songlua_hibernate_seconds")?;
            let hibernate = if theme_hibernating {
                f32::INFINITY
            } else if value == Value::Nil {
                0.
            } else {
                sprites::number(call, value)? as f32
            };
            let value = sprites::field(call, id, "__songlua_capture_tween_time_left")?;
            let left = if value == Value::Nil {
                0.
            } else {
                (sprites::number(call, value)? as f32).max(0.)
            };
            (hibernate, hibernate + left)
        };
        let mut index = 1;
        loop {
            let value = call.raw_table_get(id, Value::Number(index as f64))?;
            if value == Value::Nil {
                break;
            }
            if let Value::Table(child) = value {
                let child = hibernate + time_left(call, store, child)?;
                if left < child {
                    left = child;
                }
            }
            index += 1;
        }
        Ok(left)
    })
}

fn queue(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
    duration: f32,
    easing: &str,
    command: Option<Vec<u8>>,
) -> Result<(), Error> {
    // BeginTweening finishes the actor subtree before adding its 52nd state.
    let count = {
        let guard = store.lock().unwrap();
        let actor = &guard.actors[&id];
        actor
            .capture
            .as_ref()
            .map_or(actor.queue.len(), capture::Capture::pending_steps)
    };
    if count > 50 {
        finish(call, store, id)?;
    }
    let mut store = store.lock().unwrap();
    let queued = store.capture_scope.is_some();
    let replaying = store.replay_frame.is_some();
    let actor = store.actors.get_mut(&id).unwrap();
    if replaying {
        actor.replay.get_or_insert_with(song_replay::State::default);
    }
    let index = actor.replay.as_mut().map(|replay| {
        let index = replay.progress.len();
        replay.progress.push(Vec::new());
        index
    });
    if let Some(capture) = &mut actor.capture {
        capture.begin_tween(duration, easing, queued);
    }
    let to = *actor.destination();
    actor.queue.push_back(TweenStep {
        index,
        duration,
        left: duration,
        from: None,
        to,
        easing: easing.to_owned(),
        opt1: None,
        command,
    });
    Ok(())
}

fn duration(call: &HostCall<'_>, value: Value, sleep: bool) -> f32 {
    // The production numeric helpers parse string durations as Rust floats,
    // but reject nonfinite numeric values (Sleep retains positive infinity).
    let value = match value {
        Value::Number(value) if value.is_finite() || (sleep && value == f64::INFINITY) => {
            Some(value)
        }
        Value::String(id) => call
            .string_bytes(id)
            .and_then(|text| std::str::from_utf8(text).ok())
            .and_then(|text| text.trim().parse::<f64>().ok()),
        _ => None,
    };
    value.unwrap_or(0.0).max(0.0) as f32
}

fn native_tween(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    let duration = call.number(1)? as f32;
    if duration < 0.0 {
        return Ok(());
    }
    if duration.is_nan() {
        return Err(call.error(b"invalid tween duration"));
    }
    let names = [
        "TweenType_Linear",
        "TweenType_Accelerate",
        "TweenType_Decelerate",
        "TweenType_Spring",
        "TweenType_Bezier",
    ];
    let kind = match arg(call, 2) {
        Value::Number(index) if (0.0..5.0).contains(&index) && index.fract() == 0.0 => {
            Some(index as usize)
        }
        Value::String(id) => call
            .string_bytes(id)
            .and_then(|name| std::str::from_utf8(name).ok())
            .and_then(|name| {
                names.iter().position(|full| {
                    name == *full || name.eq_ignore_ascii_case(full.split_once('_').unwrap().1)
                })
            }),
        _ => None,
    }
    .ok_or_else(|| call.error(b"Expected TweenType"))?;
    let easing = if kind == 4 {
        let controls = table(call, arg(call, 3))?;
        let count = call.raw_table_len(controls)?;
        if count != 4 && count != 8 {
            return Ok(());
        }
        let mut points = Vec::with_capacity(count);
        for index in 1..=count {
            let value = call.raw_table_get(controls, Value::Number(index as f64))?;
            let value = call.call(helper(call, 6)?, &[value])?[0];
            let value = if let Value::Number(value) = value {
                value as f32
            } else {
                0.0
            };
            points.push(value.to_string());
        }
        format!("bezier({})", points.join(","))
    } else {
        ["linear", "inQuad", "outQuad", "spring"][kind].to_owned()
    };
    queue(call, store, actor, duration, &easing, None)
}

pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    op: Lifecycle,
) -> Result<(), Error> {
    if matches!(op, Lifecycle::Update | Lifecycle::Rate | Lifecycle::GetRate)
        && !is_frame(store, actor)
    {
        return Err(call.error(b"ActorFrame expected"));
    }
    match op {
        Lifecycle::Ease(easing) => {
            let duration = duration(call, arg(call, 1), false);
            queue(call, store, actor, duration, easing, None)?;
        }
        Lifecycle::Tween => native_tween(call, store, actor)?,
        Lifecycle::Sleep => {
            let duration = duration(call, arg(call, 1), true);
            queue(call, store, actor, duration, "linear", None)?;
            queue(call, store, actor, 0.0, "linear", None)?;
        }
        Lifecycle::Hibernate => {
            let key = call.try_intern(b"__songlua_theme_hibernating")?;
            call.raw_table_set(actor, key, Value::Boolean(false))?;
            let duration = float_scalar(call, arg(call, 1), true).unwrap_or(0.0);
            store
                .lock()
                .unwrap()
                .actors
                .get_mut(&actor)
                .unwrap()
                .hibernate = duration;
            let key = call.try_intern(b"__songlua_hibernate_seconds")?;
            call.raw_table_set(actor, key, Value::Number(duration as f64))?;
            capture::write(
                store,
                actor,
                crate::SongLuaOverlayStateDelta {
                    hibernating: Some(duration > 0.),
                    ..Default::default()
                },
                true,
            );
        }
        Lifecycle::Stop => {
            {
                let mut store = store.lock().unwrap();
                let actor = store.actors.get_mut(&actor).unwrap();
                if !capture::cancel(actor, false) {
                    actor.queue.clear();
                    actor.sync_rotation_getters();
                }
            }
            song_replay::sync_getters(call, store, actor)?;
        }
        Lifecycle::Finish => finish(call, store, actor)?,
        Lifecycle::Hurry => {
            let factor = call.number(1)? as f32;
            if factor < 0.0 {
                return Err(call.error(b"hurrytweening factor must not be negative"));
            }
            hurry(&mut store.lock().unwrap(), actor, factor);
        }
        Lifecycle::TimeLeft => {
            let left = time_left(call, store, actor)?;
            return call.push(Value::Number(left as f64));
        }
        Lifecycle::Queue | Lifecycle::QueueMessage => {
            if let Some(mut name) = command_name(call, arg(call, 1)) {
                if matches!(op, Lifecycle::QueueMessage) {
                    name.insert(0, b'!');
                }
                if !capture::queue(call, store, actor, name.clone())? {
                    queue(call, store, actor, 0.0, "linear", Some(name))?;
                }
            }
        }
        Lifecycle::Update => {
            let function = arg(call, 1);
            if !matches!(function, Value::Nil | Value::Function(_) | Value::Native(_)) {
                return Err(call.error(b"SetUpdateFunction requires a function or nil"));
            }
            let key = call.try_intern(b"__songlua_update_function")?;
            call.table_set(Value::Table(actor), key, function)?;
            invalidate_plans(call, store)?;
        }
        Lifecycle::Rate => {
            let rate = call.number(1)? as f32;
            if rate <= 0.0 {
                return Err(call.error(b"Update rate must be greater than 0"));
            }
            if rate > 0.0 {
                store
                    .lock()
                    .unwrap()
                    .actors
                    .get_mut(&actor)
                    .unwrap()
                    .update_rate = rate;
                invalidate_plans(call, store)?;
            }
        }
        Lifecycle::GetRate => {
            return call.push(Value::Number(
                store.lock().unwrap().actors[&actor].update_rate as f64,
            ));
        }
    }
    call.push(Value::Table(actor))
}

pub(super) fn start(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    if store.lock().unwrap().actors[&actor].started {
        return Ok(());
    }
    play(call, store, actor, b"Begin", None, true)?;
    startup(call, store, actor)
}

pub(super) fn end(call: &mut HostCall<'_>, store: &Shared, root: TableId) -> Result<(), Error> {
    let globals = table(call, helper(call, 5)?)?;
    let key = call.try_intern(b"__songlua_top_screen")?;
    call.raw_table_set(globals, key, Value::Nil)?;
    // The production live scene owns a synthetic root. End walks its ordinary
    // descendants in their current order, excluding that root and wrappers.
    // Commands may append tweens/queues, but End never advances them.
    for child in children(call, store, root)? {
        play(call, store, child, b"End", None, true)?;
    }
    Ok(())
}

pub(super) fn startup(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    if !store.lock().unwrap().actors.contains_key(&actor) {
        return native_children::group_lifecycle(call, store, actor, true);
    }
    if store.lock().unwrap().actors[&actor].started {
        return Ok(());
    }
    run_named(call, store, actor, b"On", None)?;
    for child in declared_children(store, actor) {
        native_children::adopt_declared(call, store, child, actor)?;
        startup(call, store, child)?;
    }
    if let Some(stream) = song_meters::stream(call, store, actor)? {
        startup(call, store, stream)?;
    }
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .started = true;
    courses::publish_raw_flag(call, store, actor, "__songlua_startup_commands_ran")?;
    Ok(())
}

fn advance_queue(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    delta: f32,
    span: f32,
) -> Result<(), Error> {
    let mut remaining = delta;
    // A meter stream hidden by an already initialized duplicate-name group
    // has never subscribed. Its stored queue/getters remain observable, but
    // production does not advance that queue without native registration.
    if !store.lock().unwrap().actors[&actor].registered {
        return Ok(());
    }
    let mut dispatched = 0;
    // Commands can replace the queue. Release metadata before entering Lua and
    // consume the original frame's remaining native float time afterwards.
    while remaining > 0.0 {
        let command = {
            let mut store = store.lock().unwrap();
            let sync = !store.clock.live.load(std::sync::atomic::Ordering::Relaxed);
            let time = store.replay_frame.map_or(0., |(_, time)| time);
            let actor = store.actors.get_mut(&actor).unwrap();
            let Some(step) = actor.queue.front_mut() else {
                break;
            };
            let beginning = step.from.is_none();
            if beginning {
                step.from = Some(actor.current);
                if let (Some(replay), Some(index)) = (&mut actor.replay, step.index) {
                    let start = if step.duration == 0. {
                        time
                    } else {
                        time - span * (remaining / delta)
                    };
                    replay.progress[index].push([start, step.duration]);
                }
            }
            let command = if beginning { step.command.take() } else { None };
            let used = remaining.min(step.left);
            step.left -= used;
            remaining -= used;
            if let (Some(replay), Some(index)) = (&mut actor.replay, step.index) {
                replay.progress[index].push([time, step.left]);
            }
            if step.left == 0.0 {
                actor.current = step.to;
                actor.queue.pop_front();
            } else {
                let factor = crate::overlay_command_ease_factor(
                    Some(&step.easing),
                    1.0 - step.left / step.duration,
                    step.opt1,
                );
                actor.current = step.from.unwrap().lerp(step.to, factor);
            }
            if sync {
                actor.sync_rotation_getters();
            }
            command
        };
        song_replay::sync_getters(call, store, actor)?;
        if let Some(command) = command {
            dispatched += 1;
            if dispatched > 10000 {
                return Err(call.error(b"nonterminating zero-time actor command queue"));
            }
            if let Some(message) = command.strip_prefix(b"!") {
                messages::queued(call, store, message)?;
            } else {
                play(call, store, actor, &command, None, true)?;
            }
        }
    }
    Ok(())
}

pub(super) struct FrameNode {
    actor: TableId,
    owned: bool,
    transition: bool,
    wrappers: Vec<FrameNode>,
    children: Vec<FrameNode>,
    columns: Vec<FrameNode>,
}
pub(super) struct Plan {
    roots: TableId,
    node: FrameNode,
}
pub(super) fn invalidate_plans(call: &mut HostCall<'_>, store: &Shared) -> Result<(), Error> {
    let plans = std::mem::take(&mut store.lock().unwrap().update_plans);
    let registry = table(call, call.captures()[0])?;
    for plan in plans.into_values() {
        call.raw_table_set(registry, Value::Table(plan.roots), Value::Nil)?;
    }
    Ok(())
}
fn plan(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    roots: TableId,
) -> Result<FrameNode, Error> {
    call.with_roots(&[Value::Table(actor)], |call| {
        let owned = store.lock().unwrap().actors.contains_key(&actor);
        let (wrappers, children) = if owned {
            let store = store.lock().unwrap();
            let node = &store.actors[&actor];
            (node.wrappers.clone(), node.children.clone())
        } else {
            // Generated duplicate-name groups have no raw native pose or queue.
            // The cached traversal still owns their table and visits their array.
            call.raw_table_set(roots, Value::Table(actor), Value::Boolean(true))?;
            (Vec::new(), native_children::group_members(call, actor)?)
        };
        let wrappers = wrappers
            .into_iter()
            .map(|id| plan(call, store, id, roots))
            .collect::<Result<_, _>>()?;
        let mut nodes = Vec::new();
        for child in children {
            native_children::adopt_declared(call, store, child, actor)?;
            nodes.push(plan(call, store, child, roots)?);
        }
        if owned && let Some(stream) = song_meters::stream(call, store, actor)? {
            nodes.push(plan(call, store, stream, roots)?);
        }
        let mut columns = Vec::new();
        for column in notefields::update_columns(call, actor)? {
            columns.push(plan(call, store, column, roots)?);
        }
        Ok(FrameNode {
            actor,
            owned,
            transition: transitions::state(call, actor)?.is_some(),
            wrappers,
            children: nodes,
            columns,
        })
    })
}

pub(super) fn advance(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    delta: f32,
) -> Result<(), Error> {
    // Production retains its traversal until an invalidating operation such as
    // SetUpdateFunction/SetUpdateRate. SortByDrawOrder alone does not invalidate
    // it. The current frame keeps its original plan even across invalidation;
    // callback values themselves are still resolved at the time of invocation.
    let cached = store.lock().unwrap().update_plans.get(&actor).cloned();
    let plan = if let Some(plan) = cached {
        plan
    } else {
        let roots = call.try_new_table()?;
        let plan = call.with_roots(&[Value::Table(roots)], |call| {
            let node = plan(call, store, actor, roots)?;
            let registry = table(call, call.captures()[0])?;
            call.raw_table_set(registry, Value::Table(roots), Value::Boolean(true))?;
            Ok(Arc::new(Plan { roots, node }))
        })?;
        store
            .lock()
            .unwrap()
            .update_plans
            .insert(actor, plan.clone());
        plan
    };
    // An authored callback may invalidate the cache and collect while this
    // frame still uses the original plan's proxy groups.
    call.with_roots(&[Value::Table(plan.roots)], |call| {
        advance_node(call, store, &plan.node, delta, delta)
    })
}

fn advance_node(
    call: &mut HostCall<'_>,
    store: &Shared,
    node: &FrameNode,
    delta: f32,
    span: f32,
) -> Result<(), Error> {
    let actor = node.actor;
    let material_delta = delta;
    let material_span = span;
    let delta = if !node.owned {
        delta
    } else {
        let mut guard = store.lock().unwrap();
        let actor = guard.actors.get_mut(&actor).unwrap();
        if actor.hibernate > 0.0 {
            let left = actor.hibernate - delta;
            actor.hibernate = left.max(0.0);
            drop(guard);
            let key = call.try_intern(b"__songlua_hibernate_seconds")?;
            call.raw_table_set(node.actor, key, Value::Number(left.max(0.0) as f64))?;
            if left <= 0.0 {
                -left
            } else {
                models::advance_materials(store, node.actor, material_delta);
                for column in &node.columns {
                    advance_node(call, store, column, material_delta, material_span)?;
                }
                return Ok(());
            }
        } else {
            delta
        }
    };
    let span = if material_delta > 0. {
        span * (delta / material_delta)
    } else {
        0.
    };
    // Wrappers receive the owner's post-hibernation delta before its update
    // rate. Their callbacks can change that rate for this same frame.
    for wrapper in &node.wrappers {
        advance_node(call, store, wrapper, delta, span)?;
    }
    let delta = if node.owned {
        let delta = delta * store.lock().unwrap().actors[&actor].update_rate;
        effects::advance(call, store, actor, delta)?;
        advance_queue(call, store, actor, delta, span)?;
        delta
    } else {
        delta
    };
    // Transition::UpdateInternal follows the owner's base queue, gates its
    // children and update callback, and tests completion before the final child
    // update. A cached plan retains whether this actor has a transition job.
    let children_active = if node.transition {
        let state = transitions::state(call, actor)?
            .ok_or_else(|| call.error(b"transition state expected"))?;
        if state != 1 {
            false
        } else {
            if let Some(child) = transitions::child(call, actor)?
                && time_left(call, store, child)? == 0.
            {
                sprites::set(call, actor, "__songlua_transition_state", Value::Number(2.))?;
            }
            true
        }
    } else {
        true
    };
    if children_active {
        for child in &node.children {
            advance_node(call, store, child, delta, span)?;
        }
    }
    models::advance_materials(store, actor, material_delta);
    let function = get(call, actor, b"__songlua_update_function")?;
    if children_active && function != Value::Nil {
        if !matches!(function, Value::Function(_) | Value::Native(_)) {
            return Err(call.error(b"actor update function must be a function"));
        }
        let result = call.with_roots(&[function], |call| {
            run_scoped(call, actor, function, Some(Value::Number(delta as f64)))
        });
        match result {
            Err(error) if error.kind() == ErrorKind::Runtime => {
                let mut store = store.lock().unwrap();
                if let Some(actor) = store.actors.get_mut(&actor) {
                    if !actor.update_error_reported {
                        actor.update_error_reported = true;
                        store.diagnostics.push(error.to_string());
                    }
                } else {
                    store.diagnostics.push(error.to_string());
                }
            }
            result => result?,
        }
    }
    // NoteField advances its column vector after its frame callback, using the
    // incoming delta outside the frame's hibernation and update-rate gates.
    for column in &node.columns {
        advance_node(call, store, column, material_delta, material_span)?;
    }
    Ok(())
}

/// Even an actor paused by an ancestor contributes a hold sample for the
/// compiler's currently running tween. Unstarted queues have no progress yet.
pub(super) fn sample_replay(actor: &mut Actor, time: f32) {
    if let (Some(replay), Some(step)) = (&mut actor.replay, actor.queue.front())
        && let Some(index) = step.index
        && step.from.is_some()
        && replay.progress[index]
            .last()
            .is_none_or(|sample| sample[0] != time)
    {
        replay.progress[index].push([time, step.left]);
    }
}

//! Song actor render bindings. Tween destinations and immediate render settings
