];

pub(super) fn field(call: &mut HostCall<'_>, actor: TableId, key: &str) -> Result<Value, Error> {
    let key = call.try_intern(key.as_bytes())?;
    call.table_get(Value::Table(actor), key)
}
pub(super) fn set(
    call: &mut HostCall<'_>,
    actor: TableId,
    key: &str,
    value: Value,
) -> Result<(), Error> {
    let key = call.try_intern(key.as_bytes())?;
    call.table_set(Value::Table(actor), key, value)
}
fn raw_set(call: &mut HostCall<'_>, actor: TableId, key: &str, value: Value) -> Result<(), Error> {
    let key = call.try_intern(key.as_bytes())?;
    call.raw_table_set(actor, key, value)
}
pub(super) fn number(call: &mut HostCall<'_>, value: Value) -> Result<f64, Error> {
    if let Value::Number(n) = value {
        return Ok(n);
    }
    match call.call(helper(call, 6)?, &[value])?[0] {
        Value::Number(n) => Ok(n),
        _ => Err(call.error(b"number expected")),
    }
}
fn optional_number(
    call: &mut HostCall<'_>,
    actor: TableId,
    key: &str,
) -> Result<Option<f32>, Error> {
    let value = field(call, actor, key)?;
    if value == Value::Nil {
        Ok(None)
    } else {
        number(call, value).map(|n| Some(n as f32))
    }
}
fn uint(call: &mut HostCall<'_>, value: Value) -> Result<u32, Error> {
    let n = number(call, value)?;
    if n > -1.0 && n < 4294967296.0 {
        Ok(n as u32)
    } else {
        Err(call.error(b"unsigned integer out of range"))
    }
}
fn optional_uint(call: &mut HostCall<'_>, actor: TableId, key: &str) -> Result<Option<u32>, Error> {
    let value = field(call, actor, key)?;
    if value == Value::Nil {
        Ok(None)
    } else {
        uint(call, value).map(Some)
    }
}
pub(super) fn vector<const N: usize>(
    call: &mut HostCall<'_>,
    value: Value,
) -> Result<Option<[f32; N]>, Error> {
    if value == Value::Nil {
        return Ok(None);
    }
    let table = table(call, value)?;
    call.with_roots(&[value], |call| {
        let mut out = [0.0; N];
        for (i, item) in out.iter_mut().enumerate() {
            let value = call.raw_table_get(table, Value::Number((i + 1) as f64))?;
            let result = call.call(helper(call, 6)?, &[value])?[0];
            let Value::Number(n) = result else {
                return Ok(None);
            };
            *item = n as f32;
        }
        Ok(Some(out))
    })
}
pub(super) fn vector_value(call: &mut HostCall<'_>, values: &[f32]) -> Result<Value, Error> {
    let table = call.try_new_table()?;
    for (i, &value) in values.iter().enumerate() {
        call.raw_table_set(
            table,
            Value::Number((i + 1) as f64),
            Value::Number(value as f64),
        )?;
    }
    Ok(Value::Table(table))
}
fn put_vector(
    call: &mut HostCall<'_>,
    actor: TableId,
    key: &str,
    values: &[f32],
) -> Result<(), Error> {
    let value = vector_value(call, values)?;
    call.with_roots(&[value], |call| set(call, actor, key, value))
}
pub(super) fn default_texture(call: &mut HostCall<'_>, actor: TableId) -> Result<bool, Error> {
    let key = call.try_intern(b"__songlua_default_texture")?;
    Ok(!matches!(
        call.raw_table_get(actor, key)?,
        Value::Nil | Value::Boolean(false)
    ))
}
pub(super) fn sheet(call: &mut HostCall<'_>, actor: TableId) -> Result<Option<(u32, u32)>, Error> {
    if default_texture(call, actor)? {
        return Ok(Some((1, 1)));
    }
    if let Some(path) = assets::texture_path(call, actor)? {
        return Ok(Some(crate::parse_sprite_sheet_dims(
            &path.to_string_lossy(),
        )));
    }
    Ok(assets::field(call, actor, b"Texture")?
        .filter(|s| !s.trim().is_empty())
        .map(|s| crate::parse_sprite_sheet_dims(s.trim())))
}
pub(super) fn image_size(path: &Path, logical: bool) -> Option<[f32; 2]> {
    if !crate::is_song_lua_image_path(path) {
        return None;
    }
    let (width, height) =
        if let Some(texture) = deadlib_assets::generated_texture(&path.to_string_lossy()) {
            (texture.source_size[0], texture.source_size[1])
        } else {
            deadlib_assets::texture_source_size(path).ok()?
        };
    let (width, height) = if logical {
        deadlib_assets::texture_source_dims_from_real(&path.to_string_lossy(), width, height)
    } else {
        (width, height)
    };
    Some([width as f32, height as f32])
}
pub(super) fn actor_upload_size(
    call: &mut HostCall<'_>,
    actor: TableId,
) -> Result<Option<[f32; 2]>, Error> {
    // These are separate authored lookups in the production reader. Keep their
    // order even when a getter changes Texture, reenters the host or collects.
    let generated = assets::texture_path(call, actor)?
        .and_then(|path| deadlib_assets::generated_texture(&path.to_string_lossy()))
        .map(|texture| texture.source_size.map(|n| n as f32));
    let image = if generated.is_some() {
        generated
    } else {
        assets::texture_path(call, actor)?
            .as_deref()
            .and_then(|path| image_size(path, false))
    };
    let Some(image) = image else { return Ok(None) };
    let path = assets::texture_path(call, actor)?.unwrap_or_default();
    let mut hints = deadlib_assets::parse_texture_hints(&path.to_string_lossy());
    hints.max_size = Some(2048);
    hints.min_size = Some(8);
    deadlib_assets::texture_image_size(image.map(|n| n as u32), &hints)
        .map(|size| Some(size.map(|n| n as f32)))
        .map_err(|error| call.error(error.to_string().as_bytes()))
}
pub(super) fn movie_size(
    call: &mut HostCall<'_>,
    actor: TableId,
) -> Result<Option<[f32; 2]>, Error> {
    let Some(path) =
        assets::texture_path(call, actor)?.filter(|path| crate::is_song_lua_video_path(path))
    else {
        return Ok(None);
    };
    let path_text = path.to_string_lossy();
    if assets::field(call, actor, b"__songlua_movie_path")?.as_deref() == Some(path_text.as_ref()) {
        let value = field(call, actor, "__songlua_movie_size")?;
        return vector(call, value);
    }
    let value = call.try_intern(path_text.as_bytes())?;
    set(call, actor, "__songlua_movie_path", value)?;
    set(call, actor, "__songlua_movie_size", Value::Nil)?;
    match deadlib_video::dimensions(&path) {
        Ok((w, h)) => {
            let size = [w as f32, h as f32];
            put_vector(call, actor, "__songlua_movie_size", &size)?;
            Ok(Some(size))
        }
        Err(error) => {
            log::warn!("Song Lua movie metadata: {error}");
            Ok(None)
        }
    }
}
pub(super) fn frame_size(
    call: &mut HostCall<'_>,
    actor: TableId,
) -> Result<Option<[f32; 2]>, Error> {
    let path = assets::texture_path(call, actor)?;
    let dims = path
        .as_deref()
        .map(|p| crate::parse_sprite_sheet_dims(&p.to_string_lossy()));
    let movie = field(call, actor, "__songlua_movie_size")?;
    let source = vector::<2>(call, movie)?
        .or_else(|| path.as_deref().and_then(|path| image_size(path, true)));
    field(call, actor, "__songlua_state_sprite_animate")?;
    optional_uint(call, actor, "__songlua_state_sprite_state_index")?;
    Ok(
        crate::sprite_image_frame_size(source.map(|[w, h]| (w, h)), false, None, dims)
            .map(|(w, h)| [w, h]),
    )
}
pub(super) fn refresh_size(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
) -> Result<(), Error> {
    let image = frame_size(call, actor)?;
    let mut store = store.lock().unwrap();
    let actor = store.actors.get_mut(&actor).unwrap();
    actor.state.size = actor
        .state
        .render
        .size
        .or_else(|| {
            actor
                .state
                .render
                .stretch_rect
                .map(|r| [r[2] - r[0], r[3] - r[1]])
        })
        .or(image)
        .unwrap_or([1.0; 2]);
    Ok(())
}
pub(super) fn is_video(call: &mut HostCall<'_>, actor: TableId) -> Result<bool, Error> {
    if let Some(path) = assets::texture_path(call, actor)? {
        return Ok(crate::is_song_lua_video_path(&path));
    }
    Ok(assets::field(call, actor, b"Texture")?
        .is_some_and(|s| crate::is_song_lua_video_path(Path::new(s.trim()))))
}
pub(super) fn decode(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    enabled: bool,
) -> Result<(), Error> {
    set(
        call,
        actor,
        "__songlua_state_decode_movie",
        Value::Boolean(enabled),
    )?;
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .state
        .render
        .decode_movie = enabled;
    Ok(())
}
pub(super) fn initialize(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    template: bool,
) -> Result<(), Error> {
    let key = call.try_intern(b"__songlua_theme_path_actor")?;
    let theme_actor = call.raw_table_get(actor, key)? == Value::Boolean(true);
    // create_theme_path_actor fills Texture after constructing the empty
    // Sprite. It leaves the decoder field and movie metadata unset; its getter
    // can still infer a movie from Texture while the initial render flag is false.
    if !theme_actor {
        let enabled = is_video(call, actor)?;
        decode(call, store, actor, enabled)?;
        movie_size(call, actor)?;
    }
    let bound = store.lock().unwrap().actors[&actor].state.class == "Banner"
        || field(call, actor, "Texture")? != Value::Nil;
    if !template {
        let mut store = store.lock().unwrap();
        let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
        render.sprite_animate = !theme_actor;
        render.sprite_texture = bound;
    }
    refresh_size(call, store, actor)
}
pub(super) fn set_texture(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    value: Value,
    clear: bool,
) -> Result<(), Error> {
    match value {
        Value::String(_) => {
            assets::text(call, value)?;
            set(call, actor, "Texture", value)?;
            raw_set(
                call,
                actor,
                "__songlua_default_texture",
                Value::Boolean(false),
            )?;
            set(call, actor, "__songlua_aft_capture_name", Value::Nil)?;
            let video = is_video(call, actor)?;
            decode(call, store, actor, video)?;
        }
        Value::Table(texture) => {
            if default_texture(call, texture)? {
                raw_set(
                    call,
                    actor,
                    "__songlua_default_texture",
                    Value::Boolean(true),
                )?;
                set(call, actor, "Texture", Value::Nil)?;
                set(call, actor, "__songlua_aft_capture_name", Value::Nil)?;
                decode(call, store, actor, false)?;
            } else if let Some(name) = assets::field(call, texture, b"__songlua_aft_capture_name")?
            {
                raw_set(
                    call,
                    actor,
                    "__songlua_default_texture",
                    Value::Boolean(false),
                )?;
                let name = call.try_intern(name.as_bytes())?;
                set(call, actor, "__songlua_aft_capture_name", name)?;
                set(call, actor, "Texture", Value::Nil)?;
                let video = is_video(call, actor)?;
                decode(call, store, actor, video)?;
            } else if let Some(path) =
                assets::field(call, texture, b"__songlua_texture_path")?.filter(|p| !p.is_empty())
            {
                let path = call.try_intern(path.as_bytes())?;
                set_texture(call, store, actor, path, false)?;
            }
        }
        Value::Nil if clear => {
            raw_set(
                call,
                actor,
                "__songlua_default_texture",
                Value::Boolean(false),
            )?;
            set(call, actor, "Texture", Value::Nil)?;
            set(call, actor, "__songlua_aft_capture_name", Value::Nil)?;
            decode(call, store, actor, false)?;
        }
        _ => {}
    }
    Ok(())
}
fn size(store: &Shared, actor: TableId, size: [f32; 2]) {
    let mut store = store.lock().unwrap();
    let actor = store.actors.get_mut(&actor).unwrap();
    actor.state.size = size;
    actor.state.render.size = Some(size);
}
fn state(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    index: u32,
    clear_rect: bool,
) -> Result<(), Error> {
    set(
        call,
        actor,
        "__songlua_state_sprite_state_index",
        Value::Number(index as f64),
    )?;
    if clear_rect {
        set(
            call,
            actor,
            "__songlua_state_custom_texture_rect",
            Value::Nil,
        )?;
    }
    let mut store = store.lock().unwrap();
    let actor = store.actors.get_mut(&actor).unwrap();
    if clear_rect {
        for clock in actor.model_materials.iter_mut().flatten() {
            clock.set_state(index.min(i32::MAX as u32) as i32);
        }
    }
    let render = &mut actor.state.render;
    render.sprite_state_index = Some(index);
    if clear_rect {
        render.custom_texture_rect = None;
    }
    Ok(())
}
fn rect(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    rect: [f32; 4],
) -> Result<(), Error> {
    state(
        call,
        store,
        actor,
        crate::SONG_LUA_SPRITE_STATE_CLEAR,
        false,
    )?;
    put_vector(call, actor, "__songlua_state_custom_texture_rect", &rect)?;
    store
        .lock()
        .unwrap()
        .actors
        .get_mut(&actor)
        .unwrap()
        .state
        .render
        .custom_texture_rect = Some(rect);
    Ok(())
}
fn current_rect(call: &mut HostCall<'_>, actor: TableId) -> Result<[f32; 4], Error> {
    let custom = field(call, actor, "__songlua_state_custom_texture_rect")?;
    let custom = vector::<4>(call, custom)?;
    let state = optional_uint(call, actor, "__songlua_state_sprite_state_index")?;
    let sheet = sheet(call, actor)?;
    Ok(crate::sprite_texture_rect(custom, state, sheet))
}
fn store_sheet(call: &mut HostCall<'_>, actor: TableId) -> Result<(), Error> {
    if let Some((cols, rows)) = sheet(call, actor)? {
        let value = vector_value(call, &[cols as f32, rows as f32])?;
        raw_set(call, actor, "__songlua_state_sprite_frame_sheet", value)?;
    }
    Ok(())
}
fn states(
    call: &mut HostCall<'_>,
    actor: TableId,
) -> Result<Vec<crate::SongLuaSpriteState>, Error> {
    let key = call.try_intern(b"__songlua_state_sprite_default_states")?;
    if !matches!(
        call.raw_table_get(actor, key)?,
        Value::Nil | Value::Boolean(false)
    ) {
        return Ok(Vec::new());
    }
    let key = call.try_intern(b"Frames")?;
    let frames = call.raw_table_get(actor, key)?;
    let mut result = Vec::new();
    if frames != Value::Nil {
        let frames_table = table(call, frames)?;
        call.with_roots(&[frames], |call| {
            let mut frame = 0;
            for i in 1usize.. {
                let value = call.raw_table_get(frames_table, Value::Number(i as f64))?;
                if value == Value::Nil {
                    break;
                }
                let entry = table(call, value)?;
                call.with_roots(&[value], |call| {
                    frame = optional_uint(call, entry, "Frame")?.unwrap_or(frame);
                    let delay = optional_number(call, entry, "Delay")?.unwrap_or(0.1);
                    result.push(crate::SongLuaSpriteState { frame, delay });
                    Ok(())
                })?;
            }
            Ok(())
        })?;
    } else {
        for i in 0i32.. {
            let Some(frame) = optional_uint(call, actor, &format!("Frame{i:04}"))? else {
                break;
            };
            let delay = optional_number(call, actor, &format!("Delay{i:04}"))?.unwrap_or(0.1);
            result.push(crate::SongLuaSpriteState { frame, delay });
        }
    }
    Ok(result)
}
fn capture(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    previous: Option<PathBuf>,
) -> Result<(), Error> {
    if !assets::field(call, actor, b"__songlua_actor_type")?.is_some_and(|kind| {
        kind.eq_ignore_ascii_case("Sprite") || kind.eq_ignore_ascii_case("Banner")
    }) {
        return Ok(());
    }
    messages::side_effect(call)?;
    let Some(path) = assets::texture_path(call, actor)? else {
        return Ok(());
    };
    if previous.as_ref() != Some(&path) {
        state(call, store, actor, 0, false)?;
        capture::write(
            store,
            actor,
            crate::SongLuaOverlayStateDelta {
                sprite_state_index: Some(0),
                ..Default::default()
            },
            true,
        );
        let globals = table(call, helper(call, 5)?)?;
        let key = call.try_intern(crate::SONG_LUA_RUNTIME_KEY.as_bytes())?;
        let runtime = call.raw_table_get(globals, key)?;
        let seconds = if runtime == Value::Nil {
            None
        } else {
            let runtime_table = table(call, runtime)?;
            Some(call.with_roots(&[runtime], |call| {
                let value = field(call, runtime_table, crate::SONG_LUA_RUNTIME_SECONDS_KEY)?;
                number(call, value).map(|n| n as f32)
            })?)
        };
        set(
            call,
            actor,
            "__songlua_state_sprite_texture_epoch",
            seconds.map_or(Value::Nil, |n| Value::Number(n as f64)),
        )?;
    }
    let Some(queued) = store.lock().unwrap().sound_capture else {
        return Ok(());
    };
    if !queued {
        let second = effects::values(call, false)?[1];
        let states = states(call, actor)?;
        let epoch = optional_number(call, actor, "__songlua_state_sprite_texture_epoch")?;
        let key = call.try_intern(b"__songlua_state_sprite_frame_sheet")?;
        let value = call.raw_table_get(actor, key)?;
        let frame_sheet = if value == Value::Nil {
            None
        } else {
            let sheet = table(call, value)?;
            Some(call.with_roots(&[value], |call| {
                let cols = call.raw_table_get(sheet, Value::Number(1.0))?;
                let cols = uint(call, cols)?;
                let rows = call.raw_table_get(sheet, Value::Number(2.0))?;
                Ok((cols, uint(call, rows)?))
            })?)
        };
        let owner = call.object_pointer(Value::Table(actor)).unwrap() as u64;
        store.lock().unwrap().sprite_textures.push((
            owner,
            crate::SongLuaSpriteTexture {
                second,
                key: Arc::from(path.to_string_lossy().as_ref()),
                path: path.clone(),
                states: states.into(),
                animation_epoch: epoch,
                frame_sheet,
            },
        ));
    }
    if let Some(player) = optional_uint(call, actor, "__songlua_judgment_sprite_player")?
        && let Some(frame_size) = frame_size(call, actor)?
    {
        let (cols, rows) = sheet(call, actor)?.unwrap_or((1, 1));
        let second = effects::values(call, false)?[1];
        store.lock().unwrap().judgment_textures.push((
            player as usize,
            crate::SongLuaJudgmentTexture {
                second,
                key: Arc::from(path.to_string_lossy().as_ref()),
                path,
                frame_size,
                frame_cols: cols as usize,
                frame_rows: rows as usize,
            },
        ));
    }
    Ok(())
}
pub(super) fn load(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    value: Value,
    preserve: bool,
) -> Result<(), Error> {
    let previous = assets::texture_path(call, actor)?;
    if preserve {
        let key = call.try_intern(b"__songlua_state_sprite_frame_sheet")?;
        let existing = call.raw_table_get(actor, key)?;
        if existing == Value::Nil {
            store_sheet(call, actor)?;
        } else {
            table(call, existing)?;
        }
    }
    set_texture(call, store, actor, value, !preserve)?;
    if !preserve {
        raw_set(
            call,
            actor,
            "__songlua_state_sprite_default_states",
            Value::Boolean(true),
        )?;
        store_sheet(call, actor)?;
    }
    let explicit = if preserve && let Value::Table(texture) = value {
        let value = field(call, texture, "__songlua_source_frame_size")?;
        vector::<2>(call, value)?
    } else {
        None
    };
    let dimensions = if explicit.is_some() {
        explicit
    } else {
        frame_size(call, actor)?
    };
    if let Some(dimensions) = dimensions {
        size(store, actor, dimensions);
        capture::write(
            store,
            actor,
            crate::SongLuaOverlayStateDelta {
                size: Some(dimensions),
                ..Default::default()
            },
            true,
        );
    }
    if preserve {
        let bound = default_texture(call, actor)?
            || assets::field(call, actor, b"__songlua_aft_capture_name")?.is_some()
            || assets::texture_path(call, actor)?.is_some();
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .state
            .render
            .sprite_texture = bound;
        capture::write(
            store,
            actor,
            crate::SongLuaOverlayStateDelta {
                sprite_texture: Some(bound),
                ..Default::default()
            },
            true,
        );
    } else if dimensions.is_some() {
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .state
            .render
            .sprite_texture = true;
        capture::write(
            store,
            actor,
            crate::SongLuaOverlayStateDelta {
                sprite_texture: Some(true),
                ..Default::default()
            },
            true,
        );
    }
    capture(call, store, actor, previous)
}

pub(super) fn texture_parameter(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
    value: Value,
) -> Result<(), Error> {
    if !store.lock().unwrap().actors.contains_key(&actor) {
        return Err(call.error(b"texture owner has been released"));
    }
    if name == "loop" {
        let value = boolish(call, value).unwrap_or(true);
        set(
            call,
            actor,
            "__songlua_state_sprite_loop",
            Value::Boolean(value),
        )?;
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .state
            .render
            .sprite_loop = value;
    } else if let Some(value) = float_scalar(call, value, false) {
        set(
            call,
            actor,
            "__songlua_state_sprite_playback_rate",
            Value::Number(value as f64),
        )?;
        store
            .lock()
            .unwrap()
            .actors
            .get_mut(&actor)
            .unwrap()
            .state
            .render
            .sprite_playback_rate = value;
    }
    Ok(())
}
pub(super) fn method(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &str,
) -> Result<(), Error> {
    let value = arg(call, 1);
    match name {
        "Load" | "LoadFromCached" | "SetTexture" => {
            let value = if name == "LoadFromCached" {
                call.arguments().get(2).copied().unwrap_or(value)
            } else {
                value
            };
            load(call, store, actor, value, name == "SetTexture")?;
        }
        "LoadBanner" | "LoadBackground" => {
            let value = call
                .coerce_string(value)?
                .ok_or_else(|| call.error(b"string expected"))?;
            call.with_roots(&[Value::String(value)], |call| {
                load(call, store, actor, Value::String(value), false)
            })?;
            return call.push(call.arguments().last().copied().unwrap_or(Value::Nil));
        }
        "GetTexture" => return textures::get(call, store, actor),
        "GetNumStates" => {
            let count = crate::sprite_frame_count(sheet(call, actor)?);
            return call.push(Value::Number(count as f64));
        }
        "GetState" => {
            let state = optional_uint(call, actor, "__songlua_state_sprite_state_index")?;
            return call.push(Value::Number(
                crate::song_lua_valid_sprite_state_index(state).unwrap_or(0) as f64,
            ));
        }
        "setstate" => {
            if let Value::Number(n) = value
                && n.is_finite()
                && (0.0..=u32::MAX as f64).contains(&n)
                && n.fract() == 0.0
            {
                state(call, store, actor, n as u32, true)?;
            }
        }
        "animate" | "texturewrapping" => {
            let enabled = boolish(call, value).unwrap_or(true);
            let mut store = store.lock().unwrap();
            let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
            if name == "animate" {
                render.sprite_animate = enabled;
            } else {
                render.texture_wrapping = enabled;
            }
        }
        "SetDecodeMovie" => decode(call, store, actor, boolish(call, value).unwrap_or(true))?,
        "GetDecodeMovie" => {
            let value = field(call, actor, "__songlua_state_decode_movie")?;
            let fallback = is_video(call, actor)?;
            return call.push(Value::Boolean(if value == Value::Nil {
                fallback
            } else {
                value != Value::Boolean(false)
            }));
        }
        "SetEffectMode" => {
            if matches!(value, Value::String(_)) && assets::text(call, value).is_ok() {
                set(call, actor, "__songlua_sprite_effect_mode", value)?;
            }
        }
        "SetAllStateDelays" => {
            if let Some(delay) = float_scalar(call, value, false) {
                let delay = delay.max(0.0);
                set(
                    call,
                    actor,
                    "__songlua_state_sprite_state_delay",
                    Value::Number(delay as f64),
                )?;
                store
                    .lock()
                    .unwrap()
                    .actors
                    .get_mut(&actor)
                    .unwrap()
                    .state
                    .render
                    .sprite_state_delay = delay;
            }
        }
        "GetAnimationLengthSeconds" => {
            let length = if let Some(length) =
                optional_number(call, actor, "__songlua_sprite_animation_length_seconds")?
            {
                length
            } else {
                optional_number(call, actor, "__songlua_state_sprite_state_delay")?
                    .unwrap_or(0.1)
                    .max(0.0)
                    * crate::sprite_frame_count(sheet(call, actor)?) as f32
            };
            return call.push(Value::Number(length as f64));
        }
        "SetSecondsIntoAnimation" => {
            if let Some(seconds) = float_scalar(call, value, false) {
                let delay = optional_number(call, actor, "__songlua_state_sprite_state_delay")?
                    .unwrap_or(0.1);
                let count = crate::sprite_frame_count(sheet(call, actor)?);
                state(
                    call,
                    store,
                    actor,
                    crate::sprite_animation_state_at(seconds, delay, count),
                    true,
                )?;
            }
        }
        "SetStateProperties" => {
            if let Value::Table(entries) = value
                && call.raw_table_len(entries)? > 0
            {
                let mut length = 0.0f32;
                let mut first = None;
                let mut first_delay = None;
                for i in 1usize.. {
                    let entry = call.raw_table_get(entries, Value::Number(i as f64))?;
                    if entry == Value::Nil {
                        break;
                    }
                    let entry_table = table(call, entry)?;
                    call.with_roots(&[entry], |call| {
                        if first.is_none() {
                            first = optional_uint(call, entry_table, "Frame")?;
                        }
                        let delay = optional_number(call, entry_table, "Delay")?
                            .unwrap_or(0.0)
                            .max(0.0);
                        first_delay.get_or_insert(delay);
                        length += delay;
                        Ok(())
                    })?;
                }
                set(
                    call,
                    actor,
                    "__songlua_sprite_animation_length_seconds",
                    Value::Number(length as f64),
                )?;
                if let Some(delay) = first_delay {
                    set(
                        call,
                        actor,
                        "__songlua_state_sprite_state_delay",
                        Value::Number(delay as f64),
                    )?;
                    store
                        .lock()
                        .unwrap()
                        .actors
                        .get_mut(&actor)
                        .unwrap()
                        .state
                        .render
                        .sprite_state_delay = delay;
                }
                state(call, store, actor, first.unwrap_or(0), true)?;
            }
        }
        "customtexturerect" | "SetCustomImageRect" => {
            let values =
                [1, 2, 3, 4].map(|i| float_scalar(call, arg(call, i), false).unwrap_or(0.0));
            rect(call, store, actor, values)?;
        }
        "stretchtexcoords" | "addimagecoords" => {
            let upload = if name == "addimagecoords" {
                let Some(size) = actor_upload_size(call, actor)? else {
                    return call.push(Value::Table(actor));
                };
                Some(size)
            } else {
                None
            };
            let delta = [1, 2].map(|i| float_scalar(call, arg(call, i), false).unwrap_or(0.0));
            let current = current_rect(call, actor)?;
            let next = if let Some(size) = upload {
                crate::texture_pixel_offset_rect(current, size, delta)
            } else {
                Some(crate::offset_texture_rect(current, delta))
            };
            if let Some(next) = next {
                rect(call, store, actor, next)?;
            }
        }
        "texturetranslate" | "texcoordvelocity" => {
            let value = [1, 2].map(|i| float_scalar(call, arg(call, i), false).unwrap_or(0.0));
            let mut store = store.lock().unwrap();
            let render = &mut store.actors.get_mut(&actor).unwrap().state.render;
            if name == "texturetranslate" {
                render.texcoord_offset = Some(value);
            } else {
                render.texcoord_velocity = Some(value);
            }
        }
        "CropTo" | "scaletoclipped" => {
            let (Some(w), Some(h)) = (
                float_scalar(call, value, false),
                float_scalar(call, arg(call, 2), false),
            ) else {
                return call.push(Value::Table(actor));
            };
            let target = [w, h];
            if name == "scaletoclipped" {
                size(store, actor, target);
            } else if target.iter().all(|n| n.is_finite() && *n > 0.0) {
                let source = match frame_size(call, actor)? {
                    Some(size) => Some(size),
                    None => movie_size(call, actor)?,
                };
                if let Some(source) = source
                    && let Some(crop) = crate::crop_texture_rect(source, target)
                {
                    size(store, actor, target);
                    rect(call, store, actor, crop)?;
                    let mut store = store.lock().unwrap();
                    let pose = store.actors.get_mut(&actor).unwrap().destination_mut();
                    pose.zoom = 1.0;
                    pose.zoom_x = 1.0;
                    pose.zoom_y = 1.0;
                    pose.zoom_z = 1.0;
                }
            }
        }
        _ => {
            return Err(call.error(
                format!("native actor method {name} has no semantic implementation").as_bytes(),
            ));
        }
    }
    call.push(Value::Table(actor))
}

//! Activation uses the loader list; the screen owns its siblings separately.
use super::super::managers::screen::Requests;
use super::super::song_activation::SongActivation;
use super::*;
use crate::{SongLuaCompileContext, SongLuaStartup};

pub(super) struct Session {
    pub roots: TableId,
    pub ready: bool,
    pub activated: bool,
    pub discovery_started: bool,
    pub locals: Option<super::super::function_snapshot::Snapshot>,
    pub queued: HashMap<TableId, super::super::SongStartupState>,
}
#[derive(Clone)]
struct Activate {
    store: Shared,
    scene: u64,
    context: SongLuaCompileContext,
    requests: Arc<Mutex<Requests>>,
    output: Arc<Mutex<Option<SongActivation>>>,
}
impl Actors {
    pub(in crate::rust_engine) fn complete_song_activation(&self, screen: ActorScene) {
        self.store
            .lock()
            .unwrap()
            .scenes
            .get_mut(&screen.id)
            .unwrap()
            .song_session
            .as_mut()
            .unwrap()
            .activated = true;
    }
    pub(in crate::rust_engine) fn discover_song_startup(
        &self,
        vm: &mut Vm,
        screen: ActorScene,
        activation: &SongActivation,
        live: bool,
    ) -> Result<(), Error> {
        let invalid = {
            let guard = self.store.lock().unwrap();
            match &guard.scenes[&screen.id].song_session {
                None => Some(b"song layers have not been initialized".as_slice()),
                Some(session) if !session.activated || session.discovery_started => {
                    Some(b"song startup discovery requires one completed activation".as_slice())
                }
                Some(_) => None,
            }
        };
        if let Some(message) = invalid {
            return vm.with_native_stack(|stack| Err(stack.error(message)));
        }
        let (root, actors, queued) = {
            let mut guard = self.store.lock().unwrap();
            let scene = guard.scenes.get_mut(&screen.id).unwrap();
            let session = scene.song_session.as_mut().unwrap();
            session.discovery_started = true;
            let root = session.roots;
            let mut actors: Vec<_> = scene
                .initial_states
                .as_ref()
                .unwrap()
                .actors
                .keys()
                .copied()
                .collect();
            actors.extend(activation.wrapper_initials.keys().copied());
            let queued = guard.startup_queues.take().unwrap_or_default();
            if live || activation.new_screen.is_some() {
                return Ok(());
            }
            (root, actors, queued)
        };
        let has_queued = !queued.is_empty();
        let locals = if has_queued {
            Some(super::super::function_snapshot::Snapshot::capture(
                vm, root, &actors,
            )?)
        } else {
            None
        };
        // Keep the attachment reachable even if a probe removes actors from
        // the authored array or replaces the global bindings that owned them.
        let first = self.store.lock().unwrap().next;
        let result = (|| {
            if !has_queued {
                return Ok(HashMap::new());
            }
            let before = self.before_song_discovery(vm, screen)?;
            self.discover_queued(vm, queued)?;
            self.after_song_discovery(vm, screen, before)
        })();
        adopt_created(&self.store, screen.id, first);
        match result {
            Ok(queued) => {
                let mut guard = self.store.lock().unwrap();
                let session = guard
                    .scenes
                    .get_mut(&screen.id)
                    .unwrap()
                    .song_session
                    .as_mut()
                    .unwrap();
                session.locals = locals;
                session.queued = queued;
                Ok(())
            }
            Err(error) => {
                if let Some(locals) = locals {
                    locals.discard(vm)?;
                }
                Err(error)
            }
        }
    }

    pub(in crate::rust_engine) fn song_startup_queued_states(
        &self,
        screen: ActorScene,
    ) -> Option<HashMap<TableId, super::super::SongStartupState>> {
        let guard = self.store.lock().unwrap();
        Some(
            guard
                .scenes
                .get(&screen.id)?
                .song_session
                .as_ref()?
                .queued
                .clone(),
        )
    }

    pub(in crate::rust_engine) fn restore_song_startup_locals(
        &self,
        vm: &mut Vm,
        screen: ActorScene,
    ) -> Result<(), Error> {
        let locals = self
            .store
            .lock()
            .unwrap()
            .scenes
            .get_mut(&screen.id)
            .unwrap()
            .song_session
            .as_mut()
            .and_then(|session| session.locals.take());
        if let Some(locals) = locals {
            locals.restore(vm)?;
        }
        Ok(())
    }

    #[cfg(feature = "test-support")]
    pub(in crate::rust_engine) fn song_startup_queue(&self) -> Vec<Value> {
        self.store
            .lock()
            .unwrap()
            .startup_queues
            .as_deref()
            .unwrap_or_default()
            .iter()
            .copied()
            .map(Value::Table)
            .collect()
    }

    pub(in crate::rust_engine) fn activate_song_layers(
        &self,
        vm: &mut Vm,
        screen: ActorScene,
        context: &SongLuaCompileContext,
        requests: Arc<Mutex<Requests>>,
    ) -> Result<SongActivation, Error> {
        let output = Arc::new(Mutex::new(None));
        let function = vm.new_host_function_with_data(
            activate,
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            Activate {
                store: self.store.clone(),
                scene: screen.id,
                context: context.clone(),
                requests,
                output: output.clone(),
            },
        )?;
        let first = self.store.lock().unwrap().next;
        let result = vm.call(function, &[]).map(|_| ());
        adopt_created(&self.store, screen.id, first);
        result?;
        Ok(output.lock().unwrap().take().unwrap())
    }
    pub(in crate::rust_engine) fn zero_song_update(
        &self,
        vm: &mut Vm,
        screen: ActorScene,
    ) -> Result<(), Error> {
        let function = vm.new_host_function_with_data(
            zero_update,
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            (self.store.clone(), screen.id),
        )?;
        let first = self.store.lock().unwrap().next;
        let result = vm.call(function, &[]).map(|_| ());
        adopt_created(&self.store, screen.id, first);
        result
    }
}
fn zero_update(call: &mut HostCall<'_>) -> Result<(), Error> {
    let (store, id) = call.function_data::<(Shared, u64)>().unwrap().clone();
    let roots = store.lock().unwrap().scenes[&id]
        .song_session
        .as_ref()
        .unwrap()
        .roots;
    zero_node(call, &store, roots)
}
fn activate(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Activate>().unwrap().clone();
    let roots = {
        let mut guard = data.store.lock().unwrap();
        if data.context.live != guard.clock.live.load(std::sync::atomic::Ordering::Relaxed) {
            return Err(call.error(b"song activation context and runtime modes differ"));
        }
        let session = guard
            .scenes
            .get_mut(&data.scene)
            .unwrap()
            .song_session
            .as_mut()
            .ok_or_else(|| call.error(b"song layers have not been initialized"))?;
        if !session.ready {
            return Err(call.error(b"song initialization failed or activation already began"));
        }
        session.ready = false;
        session.roots
    };
    call.with_roots(&[Value::Table(roots)], |call| {
        let globals = table(call, helper(call, 5)?)?;
        let retained = call.try_new_table()?;
        call.with_roots(&[Value::Table(retained)], |call| {
            // Retain initialized globals as each typed read succeeds. A later
            // getter may collect or replace the earlier global table.
            if let Some(previous) = call.table_host_state(roots)? {
                call.raw_table_set(retained, Value::Number(5.), Value::Table(previous))?;
            }
            call.set_table_host_state(roots, Some(retained))?;
            let mut initialized = [None; 4];
            for (i, key) in ["mod_actions", "mod_perframes", "mods", "mods_ease"]
                .into_iter()
                .enumerate()
            {
                let value = sprites::field(call, globals, key)?;
                if value != Value::Nil {
                    table(call, value)?;
                    call.raw_table_set(retained, Value::Number((i + 1) as f64), value)?;
                    initialized[i] = Some(value);
                }
                if i == 0 && data.requests.lock().unwrap().next.take().is_some() {
                    log::warn!("Setting a new screen during an InitCommand is not allowed.");
                }
            }
            raw_set(
                call,
                globals,
                "__songlua_screen_loading",
                Value::Boolean(false),
            )?;
            data.store
                .lock()
                .unwrap()
                .startup_queues
                .get_or_insert_with(Vec::new);
            if let Some(capture) = &mut data.store.lock().unwrap().song_broadcasts {
                capture.overlay_started = true;
            }
            // Loader children have no native parent of their own. Begin walks
            // direct unique roots; On below follows the raw sequence including aliases.
            native_children::with_children(call, roots, |call, actor| {
                let beat = get(call, actor, b"__songlua_background_start_beat")?;
                if beat != Value::Nil {
                    sprites::number(call, beat)?;
                    return Ok(());
                }
                named_tree(call, &data.store, actor, b"Begin")
            })?;
            let top = get(call, globals, b"__songlua_top_screen")?;
            if top != Value::Nil {
                call.with_roots(&[top], |call| {
                    let children = sprites::field(call, table(call, top)?, "__songlua_children")?;
                    call.with_roots(&[children], |call| {
                        let actor = get(call, table(call, children)?, b"In")?;
                        if actor != Value::Nil {
                            call.with_roots(&[actor], |call| {
                                transitions::start(call, &data.store, table(call, actor)?)
                            })?;
                        }
                        Ok(())
                    })
                })?;
            }
            #[cfg(feature = "test-support")]
            if let Some(&[music, beat, _]) = data.context.compile_clock_inputs.first() {
                let origin = data
                    .context
                    .song_timing
                    .as_ref()
                    .map_or(0., |t| f64::from(t.get_time_for_beat_exact(0.)));
                let runtime = sprites::field(call, globals, crate::SONG_LUA_RUNTIME_KEY)?;
                call.with_roots(&[runtime], |call| {
                    let runtime = table(call, runtime)?;
                    sprites::set(
                        call,
                        runtime,
                        crate::SONG_LUA_RUNTIME_BEAT_KEY,
                        Value::Number(f64::from(beat as f32)),
                    )?;
                    sprites::set(
                        call,
                        runtime,
                        crate::SONG_LUA_RUNTIME_SECONDS_KEY,
                        Value::Number(f64::from(
                            ((music - origin) / f64::from(crate::song_music_rate(&data.context)))
                                as f32,
                        )),
                    )?;
                    Ok(())
                })?;
            }
            messages::record(call, b"ScreenChanged", false)?;
            messages::dispatch(call, &data.store, b"ScreenChanged", None, true)?;
            startup(call, &data.store, roots)?;
            let wrapper_initials = song_capture::wrapper_initials(call, &data.store, roots)?;
            let options = read_options(call, globals, &data.context)?;
            *data.output.lock().unwrap() = Some(SongActivation {
                initialized_globals: initialized,
                wrapper_initials,
                updates: HashMap::new(),
                tweens: HashMap::new(),
                broadcasts: Vec::new(),
                options,
                new_screen: None,
            });
            Ok(())
        })
    })
}
fn named_tree(
    call: &mut HostCall<'_>,
    store: &Shared,
    actor: TableId,
    name: &[u8],
) -> Result<(), Error> {
    call.with_roots(&[Value::Table(actor)], |call| {
        native_children::run_command(call, store, actor, name, None)?;
        native_children::with_children(call, actor, |call, child| {
            named_tree(call, store, child, name)
        })?;
        Ok(())
    })
}
fn startup(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    call.with_roots(&[Value::Table(actor)], |call| {
        if truthy(get(call, actor, b"__songlua_defer_on")?) {
            return Ok(());
        }
        if truthy(sprites::field(
            call,
            actor,
            "__songlua_startup_commands_ran",
        )?) {
            return Ok(());
        }
        sprites::set(
            call,
            actor,
            "__songlua_startup_command_started",
            Value::Boolean(true),
        )?;
        sprites::set(
            call,
            actor,
            "__songlua_startup_children_walked",
            Value::Boolean(false),
        )?;
        native_children::run_command_with_drain(call, store, actor, b"On", None, false)?;
        // Fetch each slot after the preceding child's On: callbacks may append
        // or remove children during this walk.
        let mut i = 1;
        loop {
            let child = call.raw_table_get(actor, Value::Number(i as f64))?;
            if child == Value::Nil {
                break;
            }
            if let Value::Table(child) = child {
                call.with_roots(&[Value::Table(child)], |call| {
                    native_children::adopt_declared(call, store, child, actor)?;
                    startup(call, store, child)
                })?;
            }
            i += 1;
        }
        if store.lock().unwrap().actors.contains_key(&actor)
            && let Some(stream) = song_meters::stream(call, store, actor)?
        {
            startup(call, store, stream)?;
        }
        sprites::set(
            call,
            actor,
            "__songlua_startup_children_walked",
            Value::Boolean(true),
        )?;
        if store.lock().unwrap().actors.contains_key(&actor) {
            capture::drain_commands(call, store, actor)?;
        }
        sprites::set(
            call,
            actor,
            "__songlua_startup_commands_ran",
            Value::Boolean(true),
        )?;
        if let Some(actor) = store.lock().unwrap().actors.get_mut(&actor) {
            actor.started = true;
        }
        Ok(())
    })
}
fn read_options(
    call: &mut HostCall<'_>,
    globals: TableId,
    context: &SongLuaCompileContext,
) -> Result<SongLuaStartup, Error> {
    let mut options = SongLuaStartup::default();
    for (i, key) in crate::SONG_LUA_PLAYER_OPTIONS_KEYS.iter().enumerate() {
        if !context.players[i].enabled {
            continue;
        }
        let table = sprites::field(call, globals, key)?;
        call.with_roots(&[table], |call| {
            let value = get(
                call,
                super::table(call, table)?,
                b"__songlua_noteskin_override",
            )?;
            options.noteskins[i] = initial_state::value_text(call, value)?;
            Ok(())
        })?;
    }
    let top = sprites::field(call, globals, "__songlua_top_screen")?;
    call.with_roots(&[top], |call| {
        let top = table(call, top)?;
        let value = get(call, top, b"__songlua_min_seconds_to_music")?;
        if value != Value::Nil {
            options.min_seconds_to_music = Some(sprites::number(call, value)? as f32);
        }
        let children = sprites::field(call, top, "__songlua_children")?;
        call.with_roots(&[children], |call| {
            let actor = sprites::field(call, table(call, children)?, "In")?;
            if actor != Value::Nil {
                call.with_roots(&[actor], |call| {
                    let visible = sprites::field(call, table(call, actor)?, "__songlua_visible")?;
                    options.hide_in = visible == Value::Boolean(false);
                    Ok(())
                })?;
            }
            Ok(())
        })
    })?;
    Ok(options)
}
fn raw_set(call: &mut HostCall<'_>, actor: TableId, key: &str, value: Value) -> Result<(), Error> {
    let key = call.try_intern(key.as_bytes())?;
    call.raw_table_set(actor, key, value)
}
fn truthy(value: Value) -> bool {
    !matches!(value, Value::Nil | Value::Boolean(false))
}

pub(super) fn adopt_created(store: &Shared, owner: u64, first: u64) {
    let scenes = store
        .lock()
        .unwrap()
        .scenes
        .keys()
        .copied()
        .filter(|id| *id > first)
        .collect::<Vec<_>>();
    for scene in scenes {
        gameplay_theme::adopt_owned_scene(store, owner, scene);
    }
}

// The real startup Update(0) uses dynamic raw-array traversal, not the cached
// chronological plan. It does not dispatch future queues or transition jobs.
fn zero_node(call: &mut HostCall<'_>, store: &Shared, actor: TableId) -> Result<(), Error> {
    call.with_roots(&[Value::Table(actor)], |call| {
        if truthy(get(call, actor, b"__songlua_live_inactive")?)
            || truthy(get(call, actor, b"__songlua_theme_hibernating")?)
        {
            return Ok(());
        }
        let hibernate = get(call, actor, b"__songlua_hibernate_seconds")?;
        if hibernate != Value::Nil && sprites::number(call, hibernate)? > 0. {
            return Ok(());
        }
        let owned = store.lock().unwrap().actors.contains_key(&actor);
        let wrappers = sprites::field(call, actor, "__songlua_wrappers")?;
        if wrappers == Value::Nil && owned {
            // Rust actor bindings own their default wrapper list in metadata.
            // Resolve each slot after the previous callback, as the native raw
            // sequence walker does, so appended wrappers run in this update.
            let mut index = 0;
            loop {
                let wrapper = store.lock().unwrap().actors[&actor]
                    .wrappers
                    .get(index)
                    .copied();
                let Some(wrapper) = wrapper else {
                    break;
                };
                zero_node(call, store, wrapper)?;
                index += 1;
            }
        }
        if wrappers != Value::Nil {
            call.with_roots(&[wrappers], |call| {
                let wrappers = table(call, wrappers)?;
                let mut i = 1;
                loop {
                    let wrapper = call.raw_table_get(wrappers, Value::Number(i as f64))?;
                    if wrapper == Value::Nil {
                        break;
                    }
                    zero_node(call, store, table(call, wrapper)?)?;
                    i += 1;
                }
                Ok(())
            })?;
        }
        if owned {
            let active = {
                let guard = store.lock().unwrap();
                let render = guard.actors[&actor].state.render;
                (!render.effect_timer
                    && render.effect_clock == deadlib_present::anim::EffectClock::Time)
                    || render.effect_mode != deadlib_present::anim::EffectMode::None
                    || render.rainbow
            };
            if active {
                effects::advance(call, store, actor, 0.)?;
            }
        }
        let mut i = 1;
        loop {
            let child = call.raw_table_get(actor, Value::Number(i as f64))?;
            if child == Value::Nil {
                break;
            }
            if let Value::Table(child) = child {
                call.with_roots(&[Value::Table(child)], |call| {
                    native_children::adopt_declared(call, store, child, actor)?;
                    zero_node(call, store, child)
                })?;
            }
            i += 1;
        }
        if owned && let Some(stream) = song_meters::stream(call, store, actor)? {
            zero_node(call, store, stream)?;
        }
        let key = if truthy(get(call, actor, b"__songlua_update_pending")?) {
            b"__songlua_update_previous".as_slice()
        } else {
            b"__songlua_update_function".as_slice()
        };
        let function = get(call, actor, key)?;
        if function != Value::Nil {
            if !matches!(function, Value::Function(_) | Value::Native(_)) {
                return Err(call.error(b"actor update function must be a function"));
            }
            let result = call.with_roots(&[function], |call| {
                run_scoped(call, actor, function, Some(Value::Number(0.)))
            });
            let drain = capture::drain_commands(call, store, actor);
            match result {
                Err(error) if error.kind() == ErrorKind::Runtime => {
                    let mut guard = store.lock().unwrap();
                    let report = guard.actors.get_mut(&actor).is_none_or(|actor| {
                        let report = !actor.update_error_reported;
                        actor.update_error_reported = true;
                        report
                    });
                    if report {
                        guard.diagnostics.push(error.to_string());
                    }
                }
                result => result?,
            }
            drain?;
        }
        Ok(())
    })
}

//! The production compiler's authored file, ownership, Init and attach boundary.
use super::super::song_layers::{Entry, SongLayerPlan};
use super::*;

#[derive(Clone)]
struct Load {
    store: Shared,
    scene: u64,
    plan: SongLayerPlan,
}
impl Actors {
    pub(in crate::rust_engine) fn song_initial_states(
        &self,
        screen: ActorScene,
    ) -> Option<super::super::song_layers::SongInitialStates> {
        self.root(screen)?;
        self.store
            .lock()
            .unwrap()
            .scenes
            .get(&screen.id)?
            .initial_states
            .clone()
    }

    pub(in crate::rust_engine) fn initialize_song_layers(
        &self,
        vm: &mut Vm,
        screen: ActorScene,
        plan: &SongLayerPlan,
    ) -> Result<Option<Value>, Error> {
        if self.root(screen).is_none() {
            return Ok(None);
        }
        for (key, source, name) in [
            (
                "layer_upper_left",
                UPPER_LEFT,
                b"@theme:/BackgroundEffects/UpperLeft.lua".as_slice(),
            ),
            (
                "layer_compose",
                COMPOSE,
                b"=song layer command merge".as_slice(),
            ),
            (
                "layer_wrap",
                WRAP,
                b"@theme:/BackgroundEffects/UpperLeft.lua".as_slice(),
            ),
        ] {
            let key_value = vm.try_intern(key.as_bytes())?;
            if vm.raw_table_get(self.helpers, key_value)? == Value::Nil {
                let code = compile_named(source, name)?;
                let function = vm.execute(&code)?[0];
                super::super::put(vm, self.helpers, key, function)?;
            }
        }
        let function = vm.new_host_function_with_data(
            load,
            &[Value::Table(self.registry), Value::Table(self.helpers)],
            Load {
                store: self.store.clone(),
                scene: screen.id,
                plan: plan.clone(),
            },
        )?;
        Ok(Some(vm.call(function, &[])?[0]))
    }
}
fn load(call: &mut HostCall<'_>) -> Result<(), Error> {
    let data = call.function_data::<Load>().unwrap().clone();
    if data.plan.live
        != data
            .store
            .lock()
            .unwrap()
            .clock
            .live
            .load(std::sync::atomic::Ordering::Relaxed)
    {
        return Err(call.error(b"song layer plan and runtime modes differ"));
    }
    let top = data.store.lock().unwrap().scenes[&data.scene].root.unwrap();
    let first = data.store.lock().unwrap().next;
    let result = load_layers(call, &data, top);
    // Constructors can leave implicit templates or throw after publishing an
    // actor. Transfer every new owner even when execution/Init failed.
    let created = data
        .store
        .lock()
        .unwrap()
        .scenes
        .keys()
        .copied()
        .filter(|id| *id > first)
        .collect::<Vec<_>>();
    for scene in created {
        gameplay_theme::adopt_owned_scene(&data.store, data.scene, scene);
    }
    let roots: Vec<_> = match &result {
        Ok(value) => vec![*value],
        Err(error) => error.value().into_iter().collect(),
    };
    call.with_roots(&roots, |call| {
        lifecycle::invalidate_plans(call, &data.store)?;
        call.push(result?)
    })
}
fn load_layers(call: &mut HostCall<'_>, data: &Load, top: TableId) -> Result<Value, Error> {
    let globals = table(call, helper(call, 5)?)?;
    raw_set(
        call,
        globals,
        "__songlua_screen_loading",
        Value::Boolean(data.plan.screen_loading),
    )?;
    let roots = call.try_new_table()?;
    call.with_roots(&[Value::Table(roots)], |call| {
        // An active screen owns the scalar loader results too. Retirement keeps
        // this private edge as part of the scene graph, without an extra pin.
        let state = call.try_new_table()?;
        call.raw_table_set(state, Value::Number(1.), Value::Table(roots))?;
        if let Some(previous) = call.table_host_state(top)? {
            call.raw_table_set(state, Value::Number(2.), Value::Table(previous))?;
        }
        call.set_table_host_state(top, Some(state))?;
        let retained = call.try_new_table()?;
        call.raw_table_set(state, Value::Number(3.), Value::Table(retained))?;
        data.store.lock().unwrap().scenes.get_mut(&data.scene).unwrap().initial_states = Some(Default::default());
        data.store.lock().unwrap().scenes.get_mut(&data.scene).unwrap().song_session = Some(song_activation::Session { roots, ready: false, activated: false, discovery_started: false, locals: None, queued: HashMap::new() });
        capture_screen(call, data, retained, globals)?;
        for (index, entry) in data.plan.entries.iter().enumerate() {
            let result = execute(call, entry);
            let definition = match result {
                Ok(value) if !data.plan.live || matches!(value, Value::Table(_)) => value,
                Ok(_) => {
                    log::warn!("Failed to load song actor '{}': must return a table; using native dummy Actor", entry.path.display());
                    Value::Table(offline::dummy(call, &data.store, "Actor")?)
                }
                Err(error) if data.plan.live => {
                    log::warn!("Failed to load song actor '{}': {error}; using native dummy Actor", entry.path.display());
                    Value::Table(offline::dummy(call, &data.store, "Actor")?)
                }
                Err(error) => return Err(call.error(format!("failed to execute '{}': {error}", entry.path.display()).as_bytes())),
            };
            let value = call.with_roots(&[definition], |call| initialize_layer(call, data, entry, index, definition, retained))?;
            call.raw_table_set(roots, Value::Number((index+1) as f64), value)?;
        }
        data.store.lock().unwrap().scenes.get_mut(&data.scene).unwrap().song_session.as_mut().unwrap().ready = true;
        Ok(Value::Table(roots))
    })
}
fn execute(call: &mut HostCall<'_>, entry: &Entry) -> Result<Value, Error> {
    let path = call.try_intern(entry.path.to_string_lossy().as_bytes())?;
    call.with_roots(&[path], |call| {
        let source = call.try_intern(entry.source.to_string_lossy().as_bytes())?;
        let loader = native_children::helper_function(call, b"source_loader")?;
        let function = call.call(loader, &[path, Value::Nil, source])?[0];
        Ok(call
            .call(function, &[])?
            .first()
            .copied()
            .unwrap_or(Value::Nil))
    })
}
fn initialize_layer(
    call: &mut HostCall<'_>,
    data: &Load,
    entry: &Entry,
    index: usize,
    value: Value,
    retained: TableId,
) -> Result<Value, Error> {
    let Value::Table(actor) = value else {
        return Ok(value);
    };
    let actor = if let Some(color) = entry.color {
        upper_left(call, actor, color)?
    } else {
        actor
    };
    call.with_roots(&[Value::Table(actor)], |call| {
        let scene = materialize(call, &data.store, actor, Materialization::Construct)?;
        let actor = data.store.lock().unwrap().scenes[&scene].root.unwrap();
        gameplay_theme::adopt_owned_scene(&data.store, data.scene, scene);
        #[cfg(feature = "test-support")]
        {
            let path = call.try_intern((index + 1).to_string().as_bytes())?;
            raw_set(call, actor, "__songlua_message_path", path)?;
        }
        #[cfg(not(feature = "test-support"))]
        let _ = index;
        let globals = table(call, helper(call, 5)?)?;
        let screen = sprites::field(call, globals, "__songlua_top_screen")?;
        let screen = table(call, screen)?;
        let children = sprites::field(call, screen, "__songlua_children")?;
        let children = table(call, children)?;
        let parent = if entry.background {
            None
        } else {
            {
                let parent = sprites::field(call, children, "SongForeground")?;
                Some(table(call, parent)?)
            }
        };
        if let Some(beat) = entry.beat {
            let key = if entry.background {
                "__songlua_background_start_beat"
            } else {
                "__songlua_foreground_start_beat"
            };
            raw_set(call, actor, key, Value::Number(f64::from(beat)))?;
            raw_set(call, actor, "__songlua_defer_on", Value::Boolean(true))?;
            raw_set(call, actor, "__songlua_live_inactive", Value::Boolean(true))?;
        }
        if let Some(parent) = parent {
            parent_scene(call, &data.store, actor, Value::Table(parent), false)?;
        }
        collect_initial(call, data, retained, Value::Table(actor))?;
        prepare_init(&data.store);
        initialize(call, &data.store, actor).map_err(|error| {
            call.error(
                format!(
                    "failed to run actor init commands for '{}': {error}",
                    entry.path.display()
                )
                .as_bytes(),
            )
        })?;
        if let Some(parent) = parent {
            // Init may change the activation flag. Read its actual post-Init value.
            let beat = get(call, actor, b"__songlua_foreground_start_beat")?;
            if beat != Value::Nil {
                sprites::number(call, beat)?;
                if let Some(name) = &entry.name {
                    let value = call.try_intern(name.as_bytes())?;
                    if get(call, actor, b"__songlua_load_name")? != Value::Nil {
                        raw_set(call, actor, "__songlua_load_name", value)?;
                    }
                    raw_set(call, actor, "__songlua_native_name", value)?;
                    raw_set(call, actor, "Name", value)?;
                    data.store
                        .lock()
                        .unwrap()
                        .actors
                        .get_mut(&actor)
                        .unwrap()
                        .state
                        .name = name.as_bytes().to_vec();
                }
                let visible = sprites::field(call, actor, "visible")?;
                call.call(visible, &[Value::Table(actor), Value::Boolean(false)])?;
            }
            parent_scene(call, &data.store, actor, Value::Table(parent), true)?;
        }
        Ok(Value::Table(actor))
    })
}
fn upper_left(call: &mut HostCall<'_>, actor: TableId, color: [f32; 4]) -> Result<TableId, Error> {
    let colors = call.try_new_table()?;
    for (i, value) in color.into_iter().enumerate() {
        call.raw_table_set(
            colors,
            Value::Number((i + 1) as f64),
            Value::Number(f64::from(value)),
        )?;
    }
    let factory = native_children::helper_function(call, b"layer_upper_left")?;
    let commands = call.call(factory, &[Value::Table(colors)])?[0];
    call.with_roots(&[commands], |call| {
        let commands = table(call, commands)?;
        for name in ["OnCommand", "GainFocusCommand", "LoseFocusCommand"] {
            let key = call.try_intern(name.as_bytes())?;
            let second = call.raw_table_get(commands, key)?;
            let first = call.raw_table_get(actor, key)?;
            let value = if matches!(first, Value::Function(_) | Value::Native(_)) {
                let compose = native_children::helper_function(call, b"layer_compose")?;
                call.call(compose, &[first, second])?[0]
            } else {
                second
            };
            call.table_set(Value::Table(actor), key, value)?;
        }
        let wrap = native_children::helper_function(call, b"layer_wrap")?;
        let value = call.call(wrap, &[Value::Table(actor)])?[0];
        table(call, value)
    })
}
const UPPER_LEFT: &[u8] = br#"
return function(color)
    return {
        OnCommand = function(self)
            self:diffuse(color):effectclock('music')
            if self.GetTexture then self:GetTexture():rate(self:GetParent():GetUpdateRate()) end
        end,
        GainFocusCommand = function(self) self:play() end,
        LoseFocusCommand = function(self) self:pause() end,
    }
end
"#;
const COMPOSE: &[u8] =
    b"return function(first, second) return function(...) first(...); return second(...) end end";
const WRAP: &[u8] = b"return function(child)\n\n\nreturn Def.ActorFrame{child}\nend";

fn raw_set(call: &mut HostCall<'_>, actor: TableId, name: &str, value: Value) -> Result<(), Error> {
    let key = call.try_intern(name.as_bytes())?;
    call.raw_table_set(actor, key, value)
}

fn save_initial(
    call: &mut HostCall<'_>,
    data: &Load,
    retained: TableId,
    actor: TableId,
    screen_layer: bool,
) -> Result<(), Error> {
    call.with_roots(&[Value::Table(actor)], |call| {
        let state = initial_state::read(call, &data.store, actor)?;
        call.raw_table_set(retained, Value::Table(actor), Value::Boolean(true))?;
        let mut guard = data.store.lock().unwrap();
        let initial = guard
            .scenes
            .get_mut(&data.scene)
            .unwrap()
            .initial_states
            .as_mut()
            .unwrap();
        if screen_layer {
            initial.screen_layers.insert(actor, state);
        } else {
            initial.actors.insert(actor, state);
        }
        Ok(())
    })
}
fn collect_initial(
    call: &mut HostCall<'_>,
    data: &Load,
    retained: TableId,
    value: Value,
) -> Result<(), Error> {
    let Value::Table(actor) = value else {
        return Ok(());
    };
    call.with_roots(&[value], |call| {
        let class = sprites::field(call, actor, "__songlua_actor_type")?;
        if initial_state::value_text(call, class)?.is_some() {
            save_initial(call, data, retained, actor, false)?;
        }
        // The compiler walks raw sequence slots: aliases are visited again,
        // holes stop the walk, and wrappers are not sequence children.
        let mut index = 1;
        loop {
            let value = call.raw_table_get(actor, Value::Number(index as f64))?;
            if value == Value::Nil {
                break;
            }
            collect_initial(call, data, retained, value)?;
            index += 1;
        }
        Ok(())
    })
}
fn capture_screen(
    call: &mut HostCall<'_>,
    data: &Load,
    retained: TableId,
    globals: TableId,
) -> Result<(), Error> {
    let screen = sprites::field(call, globals, "__songlua_top_screen")?;
    call.with_roots(&[screen], |call| {
        let children = sprites::field(call, table(call, screen)?, "__songlua_children")?;
        call.with_roots(&[children], |call| {
            let children = table(call, children)?;
            for name in ["Underlay", "Overlay", "SongBackground", "In"] {
                let actor = sprites::field(call, children, name)?;
                if actor != Value::Nil {
                    save_initial(call, data, retained, table(call, actor)?, true)?;
                }
            }
            Ok(())
        })
    })?;
    for name in [
        "__songlua_top_screen_player_1",
        "__songlua_top_screen_player_2",
    ] {
        let actor = sprites::field(call, globals, name)?;
        table(call, actor)?;
        collect_initial(call, data, retained, actor)?;
    }
    Ok(())
}

//! Restore the compiler's chronological queue after speculative discovery.
use super::*;
use crate::{SongLuaOverlayState, rust_engine::SongStartupState};

// Before the first positive update, preparation getters still expose the
// exported frame-zero fields, while tween interpolation owns a different tail.
#[derive(Clone, Default)]
pub(super) struct State {
    pub(super) getters: Option<TweenPose>,
    pub(super) progress: Vec<Vec<[f32; 2]>>,
    pub(super) targets: u128,
}

#[derive(Clone)]
struct Setup {
    store: Shared,
    overlays: Vec<(TableId, SongLuaOverlayState)>,
    startup: HashMap<TableId, SongStartupState>,
    spin: HashMap<TableId, [f32; 3]>,
}

impl Actors {
    pub(in crate::rust_engine) fn begin_song_replay(
        &self,
        vm: &mut Vm,
        screen: ActorScene,
        overlays: &[(TableId, SongLuaOverlayState)],
        startup: &HashMap<TableId, SongStartupState>,
    ) -> Result<(), Error> {
        let invalid = {
            let store = self.store.lock().unwrap();
            if store.clock.live.load(std::sync::atomic::Ordering::Relaxed) {
                Some(b"song preparation replay is unavailable in live mode".as_slice())
            } else if store.playback {
                Some(b"song replay has already started".as_slice())
            } else if !store.scenes[&screen.id]
                .song_session
                .as_ref()
                .is_some_and(|session| session.activated && session.discovery_started)
            {
                Some(b"song replay requires startup discovery".as_slice())
            } else if overlays
                .iter()
                .map(|(id, _)| id)
                .chain(startup.keys())
                .any(|id| {
                    store
                        .actors
                        .get(id)
                        .is_none_or(|actor| actor.scene != screen.id)
                })
            {
                Some(b"song replay actor belongs to another scene".as_slice())
            } else {
                None
            }
        };
        if let Some(message) = invalid {
            return vm.with_native_stack(|stack| Err(stack.error(message)));
        }
        let spin = {
            let store = self.store.lock().unwrap();
            overlays
                .iter()
                .filter_map(|(id, _)| {
                    let actor = &store.actors[id];
                    actor.effects.spin_baked.then_some((
                        *id,
                        [
                            actor.current.rot_x_deg,
                            actor.current.rot_y_deg,
                            actor.current.rot_z_deg,
                        ],
                    ))
                })
                .collect()
        };
        self.restore_song_startup_locals(vm, screen)?;
        let mut captures = vec![Value::Table(self.registry), Value::Table(self.helpers)];
        captures.extend(overlays.iter().map(|(id, _)| Value::Table(*id)));
        captures.extend(startup.keys().map(|id| Value::Table(*id)));
        let function = vm.new_host_function_with_data(
            setup,
            &captures,
            Setup {
                store: self.store.clone(),
                overlays: overlays.to_vec(),
                startup: startup.clone(),
                spin,
            },
        )?;
        // General playback removes discovery queues. The saved Init/On queues
        // below are the only queues which may enter chronological preparation.
        self.begin_playback();
        vm.call(function, &[])?;
        self.store.lock().unwrap().replay_frame = Some((screen.id, 0.));
        Ok(())
    }
}

fn setup(call: &mut HostCall<'_>) -> Result<(), Error> {
    let setup = call.function_data::<Setup>().unwrap().clone();
    for &(id, state) in &setup.overlays {
        for key in [
            "__songlua_capture_cursor",
            "__songlua_capture_duration",
            "__songlua_capture_tween_time_left",
        ] {
            raw_set(call, id, key, Value::Number(0.))?;
        }
        for key in [
            "__songlua_startup_queue_seconds",
            "__songlua_capture_easing",
            "__songlua_capture_opt1",
            "__songlua_capture_opt2",
            "__songlua_capture_block",
            "__songlua_capture_immediate_block",
        ] {
            raw_set(call, id, key, Value::Nil)?;
        }
        let blocks = call.try_new_table()?;
        raw_set(call, id, "__songlua_capture_blocks", Value::Table(blocks))?;
        let binding = get(call, id, b"__songlua_startup_sprite")?;
        if binding != Value::Nil {
            call.with_roots(&[binding], |call| {
                let binding = table(call, binding)?;
                for key in [
                    "Texture",
                    "Frames",
                    "__songlua_state_sprite_default_states",
                    "__songlua_state_sprite_texture_epoch",
                    "__songlua_state_sprite_frame_sheet",
                ] {
                    let value = get(call, binding, key.as_bytes())?;
                    raw_set(call, id, key, value)?;
                }
                Ok(())
            })?;
        }
        restore_getters(call, &setup.store, id, state)?;
    }
    let mut store = setup.store.lock().unwrap();
    for (&id, startup) in setup
        .startup
        .iter()
        .filter(|(_, state)| !state.steps.is_empty())
    {
        let mut current = setup
            .overlays
            .iter()
            .find(|(actor, _)| *actor == id)
            .map_or_else(
                || crate::overlay_state_after_blocks(startup.initial, &startup.blocks, 0.),
                |(_, state)| *state,
            );
        let mut to = current;
        let actor = store.actors.get_mut(&id).unwrap();
        let getters = *actor.destination();
        let replay = actor.replay.get_or_insert(State {
            getters: Some(getters),
            ..Default::default()
        });
        replay.progress = vec![Vec::new(); startup.steps.len()];
        replay.targets = 0;
        actor.queue.clear();
        for (index, &duration) in startup.steps.iter().enumerate() {
            let mut easing = None;
            let mut opt1 = None;
            for (block, step) in startup.blocks.iter().zip(&startup.block_steps) {
                if *step == Some(index + 1) {
                    crate::apply_overlay_delta(&mut to, &block.delta);
                    for target in crate::tween_pose::TARGETS {
                        if block.delta.has_update_target(target) {
                            replay.targets |= 1u128 << target as usize;
                        }
                    }
                    easing.clone_from(&block.easing);
                    opt1 = block.opt1;
                }
            }
            actor.queue.push_back(TweenStep::startup(
                index,
                duration,
                to.into(),
                easing,
                opt1,
                startup
                    .commands
                    .get(index)
                    .cloned()
                    .flatten()
                    .map(String::into_bytes),
            ));
        }
        if let Some(rotation) = setup.spin.get(&id) {
            [current.rot_x_deg, current.rot_y_deg, current.rot_z_deg] = *rotation;
        }
        actor.current = current.into();
    }
    Ok(())
}

// Match the preparation getter export, not a wholesale render-state reset:
// discovery also writes non-tween properties which the compiler keeps.
fn restore_getters(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
    state: SongLuaOverlayState,
) -> Result<(), Error> {
    for (key, value) in [
        ("__songlua_visible", state.visible),
        ("__songlua_state_sprite_texture", state.sprite_texture),
        ("__songlua_state_aft_preserve", state.aft_preserve),
        ("__songlua_state_aft_created", state.aft_created),
        ("__songlua_state_effect_timer", state.effect_timer),
        ("__songlua_state_effect_no_offset", state.effect_no_offset),
    ] {
        sprites::set(call, id, key, Value::Boolean(value))?;
    }
    for (key, value) in [
        ("__songlua_state_aux", state.aux),
        ("__songlua_aux", state.aux),
        ("__songlua_state_x", state.x),
        ("__songlua_state_y", state.y),
        ("__songlua_state_z", state.z),
        ("__songlua_current_x", state.x),
        ("__songlua_current_y", state.y),
        ("__songlua_current_z", state.z),
        ("__songlua_state_zoom", state.zoom),
        ("__songlua_state_zoom_x", state.zoom_x),
        ("__songlua_state_zoom_y", state.zoom_y),
        ("__songlua_state_zoom_z", state.zoom_z),
        ("__songlua_state_basezoom", state.basezoom),
        ("__songlua_state_basezoom_x", state.basezoom_x),
        ("__songlua_state_basezoom_y", state.basezoom_y),
        ("__songlua_state_basezoom_z", state.basezoom_z),
        ("__songlua_state_base_alpha", state.base_alpha),
        ("__songlua_state_rot_x_deg", state.rot_x_deg),
        ("__songlua_state_rot_y_deg", state.rot_y_deg),
        ("__songlua_state_rot_z_deg", state.rot_z_deg),
        ("__songlua_state_halign", state.halign),
        ("__songlua_state_valign", state.valign),
        ("__songlua_state_effect_period", state.effect_period),
    ] {
        sprites::set(call, id, key, Value::Number(f64::from(value)))?;
    }
    for (key, values) in [
        ("__songlua_state_quaternion", state.quaternion.as_slice()),
        (
            "__songlua_state_base_rotation",
            state.base_rotation.as_slice(),
        ),
        ("__songlua_state_glow", state.glow.as_slice()),
        (
            "__songlua_state_effect_magnitude",
            state.effect_magnitude.as_slice(),
        ),
    ]
    .into_iter()
    .chain(
        state
            .size
            .as_ref()
            .map(|size| ("__songlua_state_size", size.as_slice())),
    )
    .chain(
        state
            .stretch_rect
            .as_ref()
            .map(|rect| ("__songlua_state_stretch_rect", rect.as_slice())),
    ) {
        let value = sprites::vector_value(call, values)?;
        call.with_roots(&[value], |call| sprites::set(call, id, key, value))?;
    }
    let diffuse = sprites::vector_value(call, &state.diffuse)?;
    call.with_roots(&[diffuse], |call| {
        sprites::set(call, id, "__songlua_state_diffuse", diffuse)?;
        sprites::set(call, id, "__songlua_diffuse", diffuse)
    })?;
    for (key, label) in [
        (
            "__songlua_state_effect_mode",
            crate::effect_mode_label(state.effect_mode),
        ),
        (
            "__songlua_state_effect_clock",
            crate::effect_clock_label(state.effect_clock),
        ),
    ] {
        let value = call.try_intern(label.as_bytes())?;
        call.with_roots(&[value], |call| sprites::set(call, id, key, value))?;
    }
    let mut store = store.lock().unwrap();
    let actor = store.actors.get_mut(&id).unwrap();
    actor.current.x = state.x;
    actor.current.y = state.y;
    actor.current.z = state.z;
    actor.current.aux = state.aux;
    actor.current.zoom = state.zoom;
    actor.current.zoom_x = state.zoom_x;
    actor.current.zoom_y = state.zoom_y;
    actor.current.zoom_z = state.zoom_z;
    actor.current.rot_x_deg = state.rot_x_deg;
    actor.current.rot_y_deg = state.rot_y_deg;
    actor.current.rot_z_deg = state.rot_z_deg;
    actor.current.quaternion = state.quaternion;
    actor.current.diffuse = state.diffuse;
    actor.current.glow = state.glow;
    actor.replay = Some(State {
        getters: Some(actor.current),
        ..Default::default()
    });
    actor.preparation_getters = Some([state.x, state.y, state.z, state.aux]);
    actor.state.rotation = [state.rot_x_deg, state.rot_y_deg, state.rot_z_deg];
    actor.state.visible = state.visible;
    let render = &mut actor.state.render;
    render.sprite_texture = state.sprite_texture;
    render.aft_preserve = state.aft_preserve;
    render.aft_created = state.aft_created;
    render.basezoom = state.basezoom;
    render.basezoom_x = state.basezoom_x;
    render.basezoom_y = state.basezoom_y;
    render.basezoom_z = state.basezoom_z;
    render.base_alpha = state.base_alpha;
    render.base_rotation = state.base_rotation;
    render.halign = state.halign;
    render.valign = state.valign;
    render.effect_mode = state.effect_mode;
    render.effect_clock = state.effect_clock;
    render.effect_timer = state.effect_timer;
    render.effect_no_offset = state.effect_no_offset;
    render.effect_period = state.effect_period;
    render.effect_magnitude = state.effect_magnitude;
    if let Some(size) = state.size {
        actor.state.size = size;
        render.size = Some(size);
    }
    if state.stretch_rect.is_some() {
        render.stretch_rect = state.stretch_rect;
    }
    Ok(())
}

fn raw_set(call: &mut HostCall<'_>, actor: TableId, key: &str, value: Value) -> Result<(), Error> {
    call.with_roots(&[value], |call| {
        let key = call.try_intern(key.as_bytes())?;
        call.raw_table_set(actor, key, value)
    })
}

/// Preparation exports the sampled current pose and queued destination to
/// Lua. No metadata lock survives allocation or a host API operation.
pub(super) fn sync_getters(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
) -> Result<(), Error> {
    let poses = {
        let mut store = store.lock().unwrap();
        let actor = store.actors.get_mut(&id).unwrap();
        if actor.replay.is_some() {
            actor.sync_rotation_getters();
            Some((actor.current, *actor.destination()))
        } else {
            None
        }
    };
    let Some((current, dest)) = poses else {
        return Ok(());
    };
    for (key, value) in [
        ("aux", dest.aux),
        ("x", dest.x),
        ("y", dest.y),
        ("z", dest.z),
        ("zoom", dest.zoom),
        ("zoom_x", dest.zoom_x),
        ("zoom_y", dest.zoom_y),
        ("zoom_z", dest.zoom_z),
        ("rot_x_deg", dest.rot_x_deg),
        ("rot_y_deg", dest.rot_y_deg),
        ("rot_z_deg", dest.rot_z_deg),
        ("skew_x", dest.skew_x),
        ("skew_y", dest.skew_y),
        ("cropleft", dest.cropleft),
        ("cropright", dest.cropright),
        ("croptop", dest.croptop),
        ("cropbottom", dest.cropbottom),
        ("fadeleft", dest.fadeleft),
        ("faderight", dest.faderight),
        ("fadetop", dest.fadetop),
        ("fadebottom", dest.fadebottom),
    ] {
        raw_set(
            call,
            id,
            &format!("__songlua_state_{key}"),
            Value::Number(f64::from(value)),
        )?;
    }
    for (key, values) in [
        ("__songlua_diffuse", dest.diffuse),
        ("__songlua_state_diffuse", dest.diffuse),
        ("__songlua_state_glow", dest.glow),
        ("__songlua_state_quaternion", dest.quaternion),
    ] {
        let value = sprites::vector_value(call, &values)?;
        raw_set(call, id, key, value)?;
    }
    let colors = if let Some(colors) = dest.vertex_colors {
        let table = call.try_new_table()?;
        call.with_roots(&[Value::Table(table)], |call| {
            for (i, color) in colors.iter().enumerate() {
                let value = sprites::vector_value(call, color)?;
                call.raw_table_set(table, Value::Number((i + 1) as f64), value)?;
            }
            raw_set(
                call,
                id,
                "__songlua_state_vertex_colors",
                Value::Table(table),
            )
        })?;
        true
    } else {
        false
    };
    if !colors {
        raw_set(call, id, "__songlua_state_vertex_colors", Value::Nil)?;
    }
    for (key, value) in [
        ("__songlua_aux", current.aux),
        ("__songlua_current_x", current.x),
        ("__songlua_current_y", current.y),
        ("__songlua_current_z", current.z),
    ] {
        raw_set(call, id, key, Value::Number(f64::from(value)))?;
    }
    Ok(())
}

// Scalar setters export the fields they wrote, without synchronizing unrelated
// destinations. Current XYZ/aux still come from the replay's current pose.
pub(super) fn publish_scalar(
    call: &mut HostCall<'_>,
    store: &Shared,
    id: TableId,
    name: &str,
) -> Result<(), Error> {
    let poses = {
        let store = store.lock().unwrap();
        let actor = &store.actors[&id];
        actor
            .replay
            .as_ref()
            .map(|_| (actor.current, *actor.getter_destination(), actor.state.size))
    };
    let Some((current, dest, size)) = poses else {
        return Ok(());
    };
    let keys: &[(&str, f32)] = match name {
        "x" | "addx" => &[("x", dest.x)],
        "y" | "addy" => &[("y", dest.y)],
        "z" | "addz" => &[("z", dest.z)],
        "xy" => &[("x", dest.x), ("y", dest.y)],
        "aux" => &[("aux", dest.aux)],
        "zoom" => &[
            ("zoom", dest.zoom),
            ("zoom_x", dest.zoom_x),
            ("zoom_y", dest.zoom_y),
            ("zoom_z", dest.zoom_z),
        ],
        "zoomx" => &[("zoom_x", dest.zoom_x)],
        "zoomy" => &[("zoom_y", dest.zoom_y)],
        "zoomz" => &[("zoom_z", dest.zoom_z)],
        "rotationx" | "addrotationx" => &[("rot_x_deg", dest.rot_x_deg)],
        "rotationy" | "addrotationy" => &[("rot_y_deg", dest.rot_y_deg)],
        "rotationz" | "addrotationz" => &[("rot_z_deg", dest.rot_z_deg)],
        _ => &[],
    };
    for &(key, value) in keys {
        raw_set(
            call,
            id,
            &format!("__songlua_state_{key}"),
            Value::Number(f64::from(value)),
        )?;
        let current = match key {
            "x" => Some(("__songlua_current_x", current.x)),
            "y" => Some(("__songlua_current_y", current.y)),
            "z" => Some(("__songlua_current_z", current.z)),
            "aux" => Some(("__songlua_aux", current.aux)),
            _ => None,
        };
        if let Some((key, value)) = current {
            raw_set(call, id, key, Value::Number(f64::from(value)))?;
        }
    }
    if matches!(name, "SetWidth" | "SetHeight" | "setsize") {
        let value = sprites::vector_value(call, &size)?;
        raw_set(call, id, "__songlua_state_size", value)?;
    }
    Ok(())
}

impl Actors {
    pub(in crate::rust_engine) fn advance_song_replay(
        &self,
        vm: &mut Vm,
        screen: ActorScene,
        seconds: f64,
        delta: f64,
    ) -> Result<bool, Error> {
        let first = {
            let mut store = self.store.lock().unwrap();
            if store
                .replay_frame
                .is_none_or(|(owner, _)| owner != screen.id)
            {
                drop(store);
                return vm.with_native_stack(|stack| {
                    Err(stack.error(b"song preparation replay has not started"))
                });
            }
            store.replay_frame = Some((screen.id, seconds as f32));
            store.next
        };
        let result = self.advance(vm, screen, delta);
        song_activation::adopt_created(&self.store, screen.id, first);
        result
    }

    pub(in crate::rust_engine) fn capture_song_tween_replay(
        &self,
        screen: ActorScene,
    ) -> Option<HashMap<TableId, super::super::SongTweenReplay>> {
        let mut store = self.store.lock().unwrap();
        let (owner, time) = store.replay_frame?;
        if owner != screen.id {
            return None;
        }
        let ids = store.scenes.get(&screen.id)?.actors.clone();
        let mut result = HashMap::new();
        for id in ids {
            let actor = store.actors.get_mut(&id).unwrap();
            lifecycle::sample_replay(actor, time);
            let Some(replay) = &actor.replay else {
                continue;
            };
            let values = crate::tween_pose::TARGETS
                .into_iter()
                .filter(|target| replay.targets & (1u128 << *target as usize) != 0)
                .map(|target| (target, actor.current.get(target)))
                .collect();
            result.insert(
                id,
                super::super::SongTweenReplay {
                    progress: replay.progress.clone(),
                    values,
                },
            );
        }
        Some(result)
    }
}

//! Deferred rewind of shared script state after future-command discovery.
use super::{ActorScene, RustSongRuntime, SongActivation};
use deadlib_lua::Error;

/// Immutable output from chronological preparation. Each progress row is a
/// queue step; samples are [song time, native time remaining]. Values include
/// only tween properties explicitly written by startup or replay commands.
#[derive(Clone, Debug, PartialEq)]
pub struct SongTweenReplay {
    pub progress: Vec<Vec<[f32; 2]>>,
    pub values: Vec<(
        crate::SongLuaOverlayUpdateTarget,
        crate::SongLuaOverlayUpdateValue,
    )>,
}
impl SongTweenReplay {
    /// Attach the sampled clock to the existing startup command blocks. Empty
    /// (never reached) steps leave the original block progress untouched.
    pub fn apply_startup_progress(
        &self,
        blocks: &mut [crate::SongLuaOverlayCommandBlock],
        startup: &super::SongStartupState,
    ) {
        for (block, step) in blocks.iter_mut().zip(&startup.block_steps) {
            if let Some(index) = step.and_then(|step| step.checked_sub(1))
                && let Some(samples) = self.progress.get(index)
                && !samples.is_empty()
            {
                block.progress = Some(samples.clone().into());
            }
        }
    }
}

impl RustSongRuntime {
    /// Advance preparation at an explicit song time, separate from actor delta
    /// and the script's music/beat clock. The caller sets script clocks first.
    pub fn advance_song_replay(
        &mut self,
        screen: ActorScene,
        seconds: f64,
        delta: f64,
    ) -> Result<bool, Error> {
        if self.actor_scene_root(screen).is_none() {
            return Ok(false);
        }
        self.actors
            .advance_song_replay(&mut self.vm, screen, seconds, delta)
    }

    /// Sample paused tweens and copy owned progress/pose output. Repeated reads
    /// at the same song time do not introduce duplicate hold samples. Identities
    /// remain owned by the active scene; output itself contains no Lua values.
    pub fn capture_song_tween_replay(
        &self,
        screen: ActorScene,
    ) -> Option<std::collections::HashMap<deadlib_lua::TableId, SongTweenReplay>> {
        self.actor_scene_root(screen)?;
        self.actors.capture_song_tween_replay(screen)
    }

    /// Enter chronological preparation after the compiler has read discovery
    /// output. Overlay initial states must be the compiler's frame-zero poses;
    /// callback-only actors use their captured immediate startup state.
    /// Restores shared script locals, sprite bindings and overlay getters, then
    /// reconstructs the original Init/On queues. Does not run a frame or emit
    /// compiled tracks; the caller still owns frame sampling and output capture.
    pub fn begin_song_replay(
        &mut self,
        screen: ActorScene,
        overlays: &[(deadlib_lua::TableId, crate::SongLuaOverlayState)],
        activation: &SongActivation,
    ) -> Result<bool, Error> {
        if self.actor_scene_root(screen).is_none() {
            return Ok(false);
        }
        if activation.new_screen.is_some() {
            return self.vm.with_native_stack(|stack| {
                Err(stack.error(b"replaced song screens do not enter preparation replay"))
            });
        }
        self.actors
            .begin_song_replay(&mut self.vm, screen, overlays, &activation.tweens)?;
        Ok(true)
    }

    /// Owned queued-command captures and their actual frame-zero actor states.
    /// Actor identities remain traced by the active scene. Empty before discovery
    /// or for skipped probes; foreign and retired scenes return None.
    pub fn song_startup_queued_states(
        &self,
        screen: ActorScene,
    ) -> Option<std::collections::HashMap<deadlib_lua::TableId, super::SongStartupState>> {
        self.actor_scene_root(screen)?;
        self.actors.song_startup_queued_states(screen)
    }

    /// Probe startup queues once, retaining shared script state until the
    /// compiler has read the discovered declarations. Rewind explicitly at
    /// the chronological replay boundary. Live/replaced screens skip probes.
    pub fn discover_song_startup_commands(
        &mut self,
        screen: ActorScene,
        activation: &SongActivation,
    ) -> Result<bool, Error> {
        if self.actor_scene_root(screen).is_none() {
            return Ok(false);
        }
        self.actors.discover_song_startup(
            &mut self.vm,
            screen,
            activation,
            self.clock.live.load(std::sync::atomic::Ordering::Relaxed),
        )?;
        // Probe-only requests never replace the actual startup screen.
        self.screen.state.lock().unwrap().next = None;
        Ok(true)
    }

    /// Consume the saved pre-probe globals, environments and closure locals.
    /// Actor captures remain available to the compiler's separate replay setup.
    pub fn restore_song_startup_locals(&mut self, screen: ActorScene) -> Result<bool, Error> {
        if self.actor_scene_root(screen).is_none() {
            return Ok(false);
        }
        self.actors
            .restore_song_startup_locals(&mut self.vm, screen)?;
        Ok(true)
    }
}

