    assert!(
        !pair
            .rust
            .discover_song_startup_commands(pair.scene, &activation)
            .unwrap()
    );
    let value = pair
        .rust
        .vm_mut()
        .execute(
            &compile_named(
                b"collectgarbage();return saved.actor.Read()",
                b"=retired discovery",
            )
            .unwrap(),
        )
        .unwrap()[0];
    assert_eq!(value, Value::Number(1.));
}

